window.ALGORITMOS = [{"id": "DP-Algorithms-BitmaskDP", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/BitmaskDP.cpp", "nombre": "BitmaskDP", "algoritmo": "DP sobre subconjuntos (bitmask)", "problema": "CSES 1653 - Elevator Rides (https://cses.fi/problemset/task/1653)", "cses": "https://cses.fi/problemset/task/1653", "entrada": "n x, luego n pesos", "salida": "mínimo de viajes del ascensor (capacidad x) para llevar a todos", "complejidad": "tiempo O(2^n · n), memoria O(2^n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : DP sobre subconjuntos (bitmask)\n * Problema  : CSES 1653 - Elevator Rides (https://cses.fi/problemset/task/1653)\n * Entrada   : n x, luego n pesos\n * Salida    : mínimo de viajes del ascensor (capacidad x) para llevar a todos\n * Complejidad: tiempo O(2^n · n), memoria O(2^n)\n */\n\nint main() {\n    fastio;\n    int n;\n    ll x;\n    cin >> n >> x;\n    vector<ll> w(n);\n    for (auto &v : w) cin >> v;\n\n    // dp[mask] = {viajes, peso en el último viaje} mínimo para llevar a las personas de mask\n    // dp[mask] = {viajes, peso en el último viaje} mínimo para llevar a las personas de mask\n    vector<pair<int, ll>> dp(1 << n, {n + 1, 0});\n    // se parte con un viaje vacío\n    dp[0] = {1, 0};\n    // se prueba cuál fue la última persona en subir\n    for (int mask = 1; mask < (1 << n); mask++) {\n        for (int i = 0; i < n; i++) {\n            if (!(mask >> i & 1)) continue;\n            auto [rides, last] = dp[mask ^ (1 << i)];\n            // cabe en el viaje actual o hay que abrir otro\n            if (last + w[i] <= x) last += w[i];\n            else rides++, last = w[i];\n            dp[mask] = min(dp[mask], {rides, last});\n        }\n    }\n    cout << dp[(1 << n) - 1].first << \"\\n\";\n    return 0;\n}\n"}, {"id": "DP-Algorithms-CoinChange", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/CoinChange.cpp", "nombre": "CoinChange", "algoritmo": "DP de monedas (mínimo número de monedas)", "problema": "CSES 1634 - Minimizing Coins (https://cses.fi/problemset/task/1634)", "cses": "https://cses.fi/problemset/task/1634", "entrada": "n x, luego n monedas", "salida": "mínimo de monedas para sumar x, o -1", "complejidad": "tiempo O(n·x), memoria O(x)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : DP de monedas (mínimo número de monedas)\n * Problema  : CSES 1634 - Minimizing Coins (https://cses.fi/problemset/task/1634)\n * Entrada   : n x, luego n monedas\n * Salida    : mínimo de monedas para sumar x, o -1\n * Complejidad: tiempo O(n·x), memoria O(x)\n */\n\nint main() {\n    fastio;\n    int n, target;\n    cin >> n >> target;\n    vector<int> coins(n);\n    for (int i = 0; i < n; i++) cin >> coins[i];\n\n    // dp[x] = mínimo número de monedas para sumar x\n    vector<int> dp(target+1, INT_MAX);\n    dp[0] = 0;\n    // cada moneda se puede usar muchas veces (mochila no acotada)\n    for (int c : coins) {\n        for (int x = c; x <= target; x++) {\n            // solo se usa dp[x-c] si ya era alcanzable\n            if (dp[x-c] != INT_MAX)\n                dp[x] = min(dp[x], dp[x-c] + 1);\n        }\n    }\n\n    // si dp[target] sigue en INT_MAX no hay forma de formarlo\n    int ans = dp[target];\n    cout << (ans == INT_MAX ? -1 : ans) << \"\\n\";\n    return 0;\n}\n"}, {"id": "DP-Algorithms-CoinCombinations", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/CoinCombinations.cpp", "nombre": "CoinCombinations", "algoritmo": "Conteo de formas con monedas (combinaciones y permutaciones)", "problema": "CSES 1636 - Coin Combinations II (https://cses.fi/problemset/task/1636)", "cses": "https://cses.fi/problemset/task/1636", "entrada": "n x, luego n valores de monedas", "salida": "cantidad de combinaciones (sin importar el orden) que suman x, módulo 10^9+7", "complejidad": "tiempo O(n·x), memoria O(x)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Conteo de formas con monedas (combinaciones y permutaciones)\n * Problema  : CSES 1636 - Coin Combinations II (https://cses.fi/problemset/task/1636)\n * Entrada   : n x, luego n valores de monedas\n * Salida    : cantidad de combinaciones (sin importar el orden) que suman x, módulo 10^9+7\n * Complejidad: tiempo O(n·x), memoria O(x)\n */\n\nconst int MODC = 1000000007;  // este problema pide módulo 10^9+7\n\nint main() {\n    fastio;\n    int n, x;\n    cin >> n >> x;\n    vector<int> coin(n);\n    for (auto &c : coin) cin >> c;\n\n    // combinaciones: la moneda va en el bucle externo (el orden no importa)\n    // dp[s] = formas de sumar s\n    vector<int> dp(x + 1, 0);\n    // hay una forma de sumar 0: no usar monedas\n    dp[0] = 1;\n    for (int c : coin)\n        for (int s = c; s <= x; s++)\n            dp[s] = (dp[s] + dp[s - c]) % MODC;\n    // Para contar permutaciones (Coin Combinations I, CSES 1635) se invierten los bucles:\n    // for s in 1..x: for c in coin: dp[s] += dp[s - c]\n    cout << dp[x] << \"\\n\";\n    return 0;\n}\n"}, {"id": "DP-Algorithms-EditDistance", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/EditDistance.cpp", "nombre": "EditDistance", "algoritmo": "Distancia de edición (Levenshtein)", "problema": "CSES 1639 - Edit Distance (https://cses.fi/problemset/task/1639)", "cses": "https://cses.fi/problemset/task/1639", "entrada": "dos cadenas a y b", "salida": "mínimo de operaciones (insertar, borrar, reemplazar) para convertir a en b", "complejidad": "tiempo O(n·m), memoria O(n·m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Distancia de edición (Levenshtein)\n * Problema  : CSES 1639 - Edit Distance (https://cses.fi/problemset/task/1639)\n * Entrada   : dos cadenas a y b\n * Salida    : mínimo de operaciones (insertar, borrar, reemplazar) para convertir a en b\n * Complejidad: tiempo O(n·m), memoria O(n·m)\n */\n\nint main() {\n    fastio;\n    string a, b;\n    cin >> a >> b;\n    int n = a.size(), m = b.size();\n\n    // dp[i][j] = distancia entre a[0..i) y b[0..j)\n    // dp[i][j] = distancia entre a[0..i) y b[0..j)\n    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));\n    // convertir un prefijo en vacío cuesta borrar todo (y al revés insertar)\n    for (int i = 0; i <= n; i++) dp[i][0] = i;\n    for (int j = 0; j <= m; j++) dp[0][j] = j;\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= m; j++)\n            // borrar, insertar o reemplazar (cuesta 0 si los caracteres coinciden)\n            dp[i][j] = min({dp[i - 1][j] + 1, dp[i][j - 1] + 1,\n                            dp[i - 1][j - 1] + (a[i - 1] != b[j - 1])});\n    cout << dp[n][m] << \"\\n\";\n    return 0;\n}\n"}, {"id": "DP-Algorithms-Kadane1D", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/Kadane1D.cpp", "nombre": "Kadane1D", "algoritmo": "Kadane (subarreglo de suma máxima)", "problema": "CSES 1643 - Maximum Subarray Sum (https://cses.fi/problemset/task/1643)", "cses": "https://cses.fi/problemset/task/1643", "entrada": "n, luego n enteros", "salida": "máxima suma de un subarreglo no vacío", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Kadane (subarreglo de suma máxima)\n * Problema  : CSES 1643 - Maximum Subarray Sum (https://cses.fi/problemset/task/1643)\n * Entrada   : n, luego n enteros\n * Salida    : máxima suma de un subarreglo no vacío\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<ll> a(n);\n    for (int i = 0; i < n; i++) {\n        cin >> a[i];\n    }\n    // best = mejor suma encontrada, curr = mejor suma de un subarreglo que termina en i\n    ll best = a[0], curr = a[0];\n    for (int i = 1; i < n; i++) {\n        // o se empieza un subarreglo nuevo en a[i] o se extiende el anterior\n        curr = max(a[i], curr + a[i]);\n        // se guarda el mejor resultado global\n        best = max(best, curr);\n    }\n    cout << best << \"\\n\";\n    return 0;\n}\n"}, {"id": "DP-Algorithms-Kadane2D", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/Kadane2D.cpp", "nombre": "Kadane2D", "algoritmo": "Kadane 2D (submatriz de suma máxima)", "problema": "Clásico, sin problema equivalente en CSES", "cses": "", "entrada": "R C, luego la matriz de R filas y C columnas", "salida": "máxima suma de una submatriz no vacía", "complejidad": "tiempo O(R^2 · C), memoria O(R · C)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Kadane 2D (submatriz de suma máxima)\n * Problema  : Clásico, sin problema equivalente en CSES\n * Entrada   : R C, luego la matriz de R filas y C columnas\n * Salida    : máxima suma de una submatriz no vacía\n * Complejidad: tiempo O(R^2 · C), memoria O(R · C)\n */\n\nint main() {\n    fastio;\n    int R, C;\n    cin >> R >> C;\n    vector<vector<ll>> mat(R, vector<ll>(C));\n    for (int i = 0; i < R; i++)\n        for (int j = 0; j < C; j++)\n            cin >> mat[i][j];\n\n    // se parte de -INF porque todos los valores pueden ser negativos\n    ll best = -INF;\n    // fijar fila superior y fila inferior\n    for (int top = 0; top < R; top++) {\n        // colSum[j] = suma de la columna j entre las filas top y bot\n        vector<ll> colSum(C, 0);\n        for (int bot = top; bot < R; bot++) {\n            for (int j = 0; j < C; j++)\n                // al bajar bot se suma una fila más a cada columna\n                colSum[j] += mat[bot][j];\n            // aplicar Kadane 1D sobre colSum\n            ll curr = colSum[0];\n            best = max(best, curr);\n            for (int j = 1; j < C; j++) {\n                curr = max(colSum[j], curr + colSum[j]);\n                best = max(best, curr);\n            }\n        }\n    }\n    cout << best << \"\\n\";\n    return 0;\n}\n"}, {"id": "DP-Algorithms-Knapsack", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/Knapsack.cpp", "nombre": "Knapsack", "algoritmo": "Mochila 0/1 (DP unidimensional)", "problema": "CSES 1158 - Book Shop (https://cses.fi/problemset/task/1158)", "cses": "https://cses.fi/problemset/task/1158", "entrada": "n x, luego n precios y luego n cantidades de páginas", "salida": "máximo de páginas que se pueden comprar con presupuesto x", "complejidad": "tiempo O(n·x), memoria O(x)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Mochila 0/1 (DP unidimensional)\n * Problema  : CSES 1158 - Book Shop (https://cses.fi/problemset/task/1158)\n * Entrada   : n x, luego n precios y luego n cantidades de páginas\n * Salida    : máximo de páginas que se pueden comprar con presupuesto x\n * Complejidad: tiempo O(n·x), memoria O(x)\n */\n\nint main() {\n    fastio;\n    int n, x;\n    cin >> n >> x;\n    vector<int> price(n), pages(n);\n    for (auto &p : price) cin >> p;\n    for (auto &p : pages) cin >> p;\n\n    // dp[w] = máximo de páginas con presupuesto w\n    vector<ll> dp(x + 1, 0);\n    // cada libro se usa una sola vez (mochila 0/1)\n    for (int i = 0; i < n; i++) {\n        // el presupuesto se recorre de mayor a menor para no reusar el mismo libro\n        for (int w = x; w >= price[i]; w--) {\n            // o no se compra el libro i, o se compra y se suma sus páginas\n            dp[w] = max(dp[w], dp[w - price[i]] + pages[i]);\n        }\n    }\n    cout << dp[x] << \"\\n\";\n    return 0;\n}\n"}, {"id": "DP-Algorithms-LCS", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/LCS.cpp", "nombre": "LCS", "algoritmo": "Subsecuencia común más larga (LCS) con reconstrucción", "problema": "CSES 3403 - Longest Common Subsequence (https://cses.fi/problemset/task/3403)", "cses": "https://cses.fi/problemset/task/3403", "entrada": "n m, luego los n enteros de a y los m enteros de b", "salida": "longitud de la LCS y una LCS", "complejidad": "tiempo O(n·m), memoria O(n·m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Subsecuencia común más larga (LCS) con reconstrucción\n * Problema  : CSES 3403 - Longest Common Subsequence (https://cses.fi/problemset/task/3403)\n * Entrada   : n m, luego los n enteros de a y los m enteros de b\n * Salida    : longitud de la LCS y una LCS\n * Complejidad: tiempo O(n·m), memoria O(n·m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<int> a(n), b(m);\n    for (auto &x : a) cin >> x;\n    for (auto &x : b) cin >> x;\n\n    // LCS[i][j] = longitud de la LCS de a[0..i) y b[0..j)\n    vector<vector<int>> LCS(n + 1, vector<int>(m + 1, 0));\n    // si los últimos coinciden se extiende la LCS; si no, se descarta uno de los dos\n    for (int i = 1; i <= n; ++i)\n        for (int j = 1; j <= m; ++j)\n            if (a[i - 1] == b[j - 1])\n                LCS[i][j] = LCS[i - 1][j - 1] + 1;\n            else\n                LCS[i][j] = max(LCS[i - 1][j], LCS[i][j - 1]);\n\n    // reconstrucción desde el final\n    // se camina desde (n, m) hacia atrás para recuperar una LCS\n    vector<int> res;\n    int i = n, j = m;\n    while (i > 0 && j > 0) {\n        if (a[i - 1] == b[j - 1]) {\n            res.push_back(a[i - 1]);\n            i--, j--;\n        }\n        else if (LCS[i - 1][j] >= LCS[i][j - 1]) i--;\n        else j--;\n    }\n    // se construyó al revés\n    reverse(all(res));\n\n    cout << LCS[n][m] << \"\\n\";\n    for (int x : res) cout << x << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n"}, {"id": "DP-Algorithms-LIS-I", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/LIS-I.cpp", "nombre": "LIS-I", "algoritmo": "LIS con DP cuadrática", "problema": "CSES 1145 - Increasing Subsequence (https://cses.fi/problemset/task/1145) (da TLE con n = 2·10^5; sirve para n <= 5000)", "cses": "https://cses.fi/problemset/task/1145", "entrada": "n, luego n enteros", "salida": "longitud de la subsecuencia creciente más larga", "complejidad": "tiempo O(n^2), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : LIS con DP cuadrática\n * Problema  : CSES 1145 - Increasing Subsequence (https://cses.fi/problemset/task/1145) (da TLE con n = 2·10^5; sirve para n <= 5000)\n * Entrada   : n, luego n enteros\n * Salida    : longitud de la subsecuencia creciente más larga\n * Complejidad: tiempo O(n^2), memoria O(n)\n */\n\nint main(){\n    fastio;\n    \n    ll n; cin >> n;\n    vector<ll> a(n); for(auto &x: a) cin >> x;\n\n\n    // DP[i] = longitud de la LIS que termina en a[i]\n    vector<ll> DP(n, 1);\n    for(int i = 1; i < n; i++){\n        // se prueba extender cada subsecuencia anterior más pequeña\n        for(int j = 0; j < i; j++){\n            if(a[j] < a[i]){\n                // a[i] se agrega al final de la LIS que termina en a[j]\n                DP[i] = max(DP[i], 1 + DP[j]);\n            }\n        }\n    }\n\n    // la respuesta es el mejor DP[i] (O(n^2), lento para n grande)\n    cout << *max_element(all(DP)) << \"\\n\";\n    \n    return 0;\n}\n"}, {"id": "DP-Algorithms-LIS-II", "carpeta": "DP", "area": "Programación dinámica", "sub": "Algorithms", "archivo": "DP/Algorithms/LIS-II.cpp", "nombre": "LIS-II", "algoritmo": "LIS con búsqueda binaria", "problema": "CSES 1145 - Increasing Subsequence (https://cses.fi/problemset/task/1145)", "cses": "https://cses.fi/problemset/task/1145", "entrada": "n, luego n enteros", "salida": "longitud de la subsecuencia creciente más larga", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : LIS con búsqueda binaria\n * Problema  : CSES 1145 - Increasing Subsequence (https://cses.fi/problemset/task/1145)\n * Entrada   : n, luego n enteros\n * Salida    : longitud de la subsecuencia creciente más larga\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint main(){\n    fastio;\n    \n    ll n; cin >> n;\n    vector<ll> a(n); for(auto &x: a) cin >> x;\n\n\n    // R[k] = menor valor final posible de una LIS de longitud k+1 (siempre ordenado)\n    vector<ll> R;\n    // M[k] = índice del elemento que está en R[k]\n    vector<ll> M;\n\n    for(int i = 0; i < n; ++i) {\n        // primer lugar de R con valor >= a[i] (búsqueda binaria)\n        auto it = lower_bound(all(R), a[i]);\n        ll ind = it - R.begin();\n\n        // a[i] es mayor que todos: la LIS crece\n        if (ind == R.size()) {\n            R.push_back(a[i]);\n            M.push_back(i);\n        } \n        else {\n            // a[i] reemplaza un final más grande para dejar más espacio a futuro\n            R[ind] = a[i];\n            M[ind] = i;\n        }\n    }\n\n    // el tamaño de R es la longitud de la LIS\n    cout << R.size() << \"\\n\";\n    \n}\n"}, {"id": "DP-Classic-Problems-Campeonato", "carpeta": "DP", "area": "Programación dinámica", "sub": "Classic Problems", "archivo": "DP/Classic Problems/Campeonato.cpp", "nombre": "Campeonato", "algoritmo": "DP de probabilidades (serie al primero en llegar a n victorias)", "problema": "Clásico \"Campeonato\"/World Series, sin problema equivalente en CSES", "cses": "", "entrada": "n p: victorias que necesita cada equipo y probabilidad p de que gane el equipo A un partido", "salida": "probabilidad de que A gane la serie (10 decimales)", "complejidad": "tiempo O(n^2), memoria O(n^2)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : DP de probabilidades (serie al primero en llegar a n victorias)\n * Problema  : Clásico \"Campeonato\"/World Series, sin problema equivalente en CSES\n * Entrada   : n p: victorias que necesita cada equipo y probabilidad p de que gane el equipo A un partido\n * Salida    : probabilidad de que A gane la serie (10 decimales)\n * Complejidad: tiempo O(n^2), memoria O(n^2)\n */\n\nint main() {\n    fastio;\n    int n;\n    double p;\n    cin >> n >> p;\n    // q = probabilidad de que gane B\n    double q = 1 - p;\n\n    // P[i][j] = probabilidad de que A gane si le faltan i victorias y a B le faltan j\n    vector<vector<double>> P(n + 1, vector<double>(n + 1, 0.0));\n    // casos base: si A ya ganó la serie la probabilidad es 1\n    for (int i = 1; i <= n; i++) P[0][i] = 1.0;  // A ya ganó\n    // si B ya ganó, es 0\n    for (int j = 1; j <= n; j++) P[j][0] = 0.0;  // B ya ganó\n    for (int i = 1; i <= n; i++)\n        for (int j = 1; j <= n; j++)\n            // se juega un partido: gana A (falta una victoria menos) o gana B\n            P[i][j] = p * P[i - 1][j] + q * P[i][j - 1];\n\n    precision(10);\n    cout << P[n][n] << \"\\n\";\n    return 0;\n}\n"}, {"id": "Data-Structures-Algorithms-Deque", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/Deque.cpp", "nombre": "Deque", "algoritmo": "Deque monótona (mínimo de ventana deslizante)", "problema": "CSES 3221 - Sliding Window Minimum (https://cses.fi/problemset/task/3221)", "cses": "https://cses.fi/problemset/task/3221", "entrada": "n k, luego x a b c con x_i = (a·x_{i-1} + b) mod c", "salida": "XOR de los mínimos de todas las ventanas de tamaño k", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Deque monótona (mínimo de ventana deslizante)\n * Problema  : CSES 3221 - Sliding Window Minimum (https://cses.fi/problemset/task/3221)\n * Entrada   : n k, luego x a b c con x_i = (a·x_{i-1} + b) mod c\n * Salida    : XOR de los mínimos de todas las ventanas de tamaño k\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    ll n, k, x, a, b, c;\n    cin >> n >> k >> x >> a >> b >> c;\n    vector<ll> v(n);\n    v[0] = x;\n    for (int i = 1; i < n; i++) v[i] = (a * v[i - 1] + b) % c;\n\n    // la deque guarda índices con valores crecientes; el frente es el mínimo de la ventana\n    // la deque guarda índices con valores crecientes; el frente es el mínimo de la ventana\n    deque<int> d;\n    ll res = 0;\n    for (int i = 0; i < n; i++) {\n        // se descartan los mayores o iguales a v[i]: nunca serán mínimo\n        while (!d.empty() && v[d.back()] >= v[i]) d.pop_back();\n        d.push_back(i);\n        // el frente salió de la ventana\n        if (d.front() <= i - k) d.pop_front();\n        // la ventana ya tiene k elementos\n        if (i >= k - 1) res ^= v[d.front()];\n    }\n    cout << res << \"\\n\";\n    return 0;\n}\n"}, {"id": "Data-Structures-Algorithms-FenwickTree", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/FenwickTree.cpp", "nombre": "FenwickTree", "algoritmo": "Fenwick Tree (BIT)", "problema": "CSES 1648 - Dynamic Range Sum Queries (https://cses.fi/problemset/task/1648)", "cses": "https://cses.fi/problemset/task/1648", "entrada": "n q, n enteros, luego q consultas: \"1 k u\" (a[k] = u) o \"2 a b\" (suma)", "salida": "la suma de cada consulta de tipo 2", "complejidad": "tiempo O((n + q) log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Fenwick Tree (BIT)\n * Problema  : CSES 1648 - Dynamic Range Sum Queries (https://cses.fi/problemset/task/1648)\n * Entrada   : n q, n enteros, luego q consultas: \"1 k u\" (a[k] = u) o \"2 a b\" (suma)\n * Salida    : la suma de cada consulta de tipo 2\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n */\n\n// Fenwick Tree (BIT): bit[i] guarda la suma de un bloque de tamaño (i & -i) que termina en i\nstruct Fenwick {\n    int n;\n    vector<ll> bit;\n\n    Fenwick(int n): n(n), bit(n + 1, 0) {}\n\n    // suma v a la posicion i (1-indexado)\n    void add(int i, ll v) {\n        for (; i <= n; i += i & -i) bit[i] += v;\n    }\n\n    // suma del prefijo [1..i]\n    ll query(int i) {\n        ll res = 0;\n        for (; i > 0; i -= i & -i) res += bit[i];\n        return res;\n    }\n\n    // suma del rango [l..r]\n    ll query(int l, int r) {\n        return query(r) - query(l - 1);\n    }\n};\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    vector<ll> a(n + 1, 0);\n    // a[] se guarda aparte para saber cuánto cambiar al actualizar\n    Fenwick fw(n);\n    for (int i = 1; i <= n; i++) {\n        cin >> a[i];\n        fw.add(i, a[i]);\n    }\n\n    while (q--) {\n        int type; cin >> type;\n        if (type == 1) {\n            // a[k] = u\n            int k; ll u; cin >> k >> u;\n            // una asignación es sumar la diferencia\n            fw.add(k, u - a[k]);\n            a[k] = u;\n        } else {\n            int l, r; cin >> l >> r;\n            cout << fw.query(l, r) << \"\\n\";\n        }\n    }\n    return 0;\n}\n"}, {"id": "Data-Structures-Algorithms-Heap", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/Heap.cpp", "nombre": "Heap", "algoritmo": "Cola de prioridad (min-heap) para asignar recursos", "problema": "CSES 1164 - Room Allocation (https://cses.fi/problemset/task/1164)", "cses": "https://cses.fi/problemset/task/1164", "entrada": "n, luego n pares \"llegada salida\"", "salida": "mínimo de habitaciones y la habitación de cada cliente", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Cola de prioridad (min-heap) para asignar recursos\n * Problema  : CSES 1164 - Room Allocation (https://cses.fi/problemset/task/1164)\n * Entrada   : n, luego n pares \"llegada salida\"\n * Salida    : mínimo de habitaciones y la habitación de cada cliente\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<array<int, 3>> c(n);  // {llegada, salida, índice}\n    for (int i = 0; i < n; i++) {\n        cin >> c[i][0] >> c[i][1];\n        c[i][2] = i;\n    }\n    sort(all(c));\n\n    // min-heap de {salida, habitación}\n    // min-heap de {salida, habitación}: la habitación que se libera primero\n    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> heap;\n    vector<int> room(n);\n    int rooms = 0;\n    for (auto &cl : c) {\n        int r;\n        // si la habitación más pronta ya se liberó, se reutiliza\n        if (!heap.empty() && heap.top().first < cl[0]) {\n            r = heap.top().second;\n            heap.pop();\n        }\n        // si no, se abre una habitación nueva\n        else r = ++rooms;\n        room[cl[2]] = r;\n        heap.push({cl[1], r});\n    }\n\n    cout << rooms << \"\\n\";\n    for (int x : room) cout << x << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n"}, {"id": "Data-Structures-Algorithms-MoAlgorithm", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/MoAlgorithm.cpp", "nombre": "MoAlgorithm", "algoritmo": "Algoritmo de Mo (consultas offline con raíz cuadrada)", "problema": "CSES 1734 - Distinct Values Queries (https://cses.fi/problemset/task/1734)", "cses": "https://cses.fi/problemset/task/1734", "entrada": "n q, n enteros, luego q consultas \"a b\"", "salida": "cantidad de valores distintos en cada rango [a, b]", "complejidad": "tiempo O((n + q) √n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Algoritmo de Mo (consultas offline con raíz cuadrada)\n * Problema  : CSES 1734 - Distinct Values Queries (https://cses.fi/problemset/task/1734)\n * Entrada   : n q, n enteros, luego q consultas \"a b\"\n * Salida    : cantidad de valores distintos en cada rango [a, b]\n * Complejidad: tiempo O((n + q) √n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    vector<int> a(n);\n    for (auto &x : a) cin >> x;\n    // comprimir valores\n    // se comprimen los valores a 0..k-1\n    vector<int> vals = a;\n    sort(all(vals));\n    vals.erase(unique(all(vals)), vals.end());\n    for (auto &x : a) x = lower_bound(all(vals), x) - vals.begin();\n\n    // tamaño de bloque ≈ √n\n    int block = max(1, (int)sqrt(n));\n    vector<array<int, 3>> queries(q);  // {l, r, índice}\n    for (int i = 0; i < q; i++) {\n        cin >> queries[i][0] >> queries[i][1];\n        queries[i][0]--, queries[i][1]--;\n        queries[i][2] = i;\n    }\n    // se ordenan las consultas por bloque del extremo izquierdo (y alternando el derecho)\n    sort(all(queries), [&](const array<int, 3> &x, const array<int, 3> &y) {\n        int bx = x[0] / block, by = y[0] / block;\n        if (bx != by) return bx < by;\n        return (bx & 1) ? x[1] > y[1] : x[1] < y[1];\n    });\n\n    // cnt[v] = apariciones de v en la ventana actual, distinct = valores distintos\n    vector<int> cnt(vals.size(), 0), ans(q);\n    int distinct = 0, L = 0, R = -1;\n    auto add = [&](int i) { if (cnt[a[i]]++ == 0) distinct++; };\n    auto del = [&](int i) { if (--cnt[a[i]] == 0) distinct--; };\n    // se mueven los extremos de la ventana de una consulta a la siguiente\n    for (auto &[l, r, id] : queries) {\n        while (L > l) add(--L);\n        while (R < r) add(++R);\n        while (L < l) del(L++);\n        while (R > r) del(R--);\n        ans[id] = distinct;\n    }\n    for (int x : ans) cout << x << \"\\n\";\n    return 0;\n}\n"}, {"id": "Data-Structures-Algorithms-SegmentTree", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/SegmentTree.cpp", "nombre": "SegmentTree", "algoritmo": "Segment Tree con propagación perezosa (suma de rango, asignación y suma de rango)", "problema": "CSES 1735 - Range Updates and Sums (https://cses.fi/problemset/task/1735)", "cses": "https://cses.fi/problemset/task/1735", "entrada": "n q, n enteros, luego q consultas: \"1 a b x\" (suma x), \"2 a b x\" (asigna x) o \"3 a b\" (consulta suma)", "salida": "la suma de cada consulta de tipo 3", "complejidad": "tiempo O((n + q) log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Segment Tree con propagación perezosa (suma de rango, asignación y suma de rango)\n * Problema  : CSES 1735 - Range Updates and Sums (https://cses.fi/problemset/task/1735)\n * Entrada   : n q, n enteros, luego q consultas: \"1 a b x\" (suma x), \"2 a b x\" (asigna x) o \"3 a b\" (consulta suma)\n * Salida    : la suma de cada consulta de tipo 3\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n */\n\n// Data: información que guarda cada nodo (suma del rango y su tamaño)\nstruct Data {\n    ll suma, size;\n    Data(): suma(0), size(0) {}\n    Data(ll s): suma(s), size(1) {}\n\n    Data(const Data &left, const Data &right) {\n        suma = left.suma + right.suma;\n        size = left.size + right.size;\n    }\n};\n\n// Primero se asigna \"value\" (si set) y luego se suma \"add\"\n// Lazy: actualización pendiente que se aplica a los hijos cuando hace falta\nstruct Lazy {\n    bool set;\n    ll value, add;\n    Lazy(): set(false), value(0), add(0) {}\n\n    static Lazy Add(ll v) { Lazy l; l.add = v; return l; }\n    static Lazy Set(ll v) { Lazy l; l.set = true; l.value = v; return l; }\n\n    bool empty() const { return !set && add == 0; }\n\n    void updateData(Data &data) const {\n        if (set) data.suma = value * data.size;\n        data.suma += add * data.size;\n    }\n\n    // compone: aplica \"other\" después de this\n    void updateLazy(const Lazy &other) {\n        if (other.set) *this = other;\n        else add += other.add;\n    }\n};\n\n// Segment Tree con propagación perezosa\nstruct SegmentTree {\n    int n;\n    vector<Data> data;\n    vector<Lazy> lazy;\n\n    SegmentTree(const vector<ll> &A) {\n        n = A.size();\n        data.assign(4 * n, Data());\n        lazy.assign(4 * n, Lazy());\n        build(A, 1, 0, n - 1);\n    }\n\n    // construye el árbol recursivamente\n    void build(const vector<ll> &A, int index, int left, int right) {\n        if (left == right) { data[index] = Data(A[left]); return; }\n        int mid = (left + right) / 2;\n        build(A, 2 * index, left, mid);\n        build(A, 2 * index + 1, mid + 1, right);\n        data[index] = Data(data[2 * index], data[2 * index + 1]);\n    }\n\n    // aplica una actualización a un nodo y la deja pendiente para sus hijos\n    void apply(int index, const Lazy &l) {\n        l.updateData(data[index]);\n        lazy[index].updateLazy(l);\n    }\n\n    // empuja la actualización pendiente a los hijos\n    void propagate(int index) {\n        if (lazy[index].empty()) return;\n        apply(2 * index, lazy[index]);\n        apply(2 * index + 1, lazy[index]);\n        lazy[index] = Lazy();\n    }\n\n    // actualiza el rango [lower, upper]\n    void update(int index, int left, int right, int lower, int upper, const Lazy &value) {\n        if (left > upper || right < lower) return;\n        if (lower <= left && right <= upper) { apply(index, value); return; }\n        propagate(index);\n        int mid = (left + right) / 2;\n        update(2 * index, left, mid, lower, upper, value);\n        update(2 * index + 1, mid + 1, right, lower, upper, value);\n        data[index] = Data(data[2 * index], data[2 * index + 1]);\n    }\n\n    // suma en el rango [lower, upper]\n    ll query(int index, int left, int right, int lower, int upper) {\n        if (left > upper || right < lower) return 0;\n        if (lower <= left && right <= upper) return data[index].suma;\n        propagate(index);\n        int mid = (left + right) / 2;\n        return query(2 * index, left, mid, lower, upper) + query(2 * index + 1, mid + 1, right, lower, upper);\n    }\n};\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    vector<ll> a(n);\n    for (auto &x : a) cin >> x;\n\n    SegmentTree Tree(a);\n    while (q--) {\n        int type, l, r;\n        cin >> type >> l >> r;\n        l--, r--;\n        if (type == 1) { ll x; cin >> x; Tree.update(1, 0, n - 1, l, r, Lazy::Add(x)); }\n        else if (type == 2) { ll x; cin >> x; Tree.update(1, 0, n - 1, l, r, Lazy::Set(x)); }\n        else cout << Tree.query(1, 0, n - 1, l, r) << \"\\n\";\n    }\n    return 0;\n}\n"}, {"id": "Data-Structures-Algorithms-SegmentTreeMin", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/SegmentTreeMin.cpp", "nombre": "SegmentTreeMin", "algoritmo": "Segment Tree iterativo (mínimo de rango y actualización puntual)", "problema": "CSES 1649 - Dynamic Range Minimum Queries (https://cses.fi/problemset/task/1649)", "cses": "https://cses.fi/problemset/task/1649", "entrada": "n q, n enteros, luego q consultas: \"1 k u\" (a[k] = u) o \"2 a b\" (mínimo en [a, b])", "salida": "el mínimo de cada consulta de tipo 2", "complejidad": "tiempo O((n + q) log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Segment Tree iterativo (mínimo de rango y actualización puntual)\n * Problema  : CSES 1649 - Dynamic Range Minimum Queries (https://cses.fi/problemset/task/1649)\n * Entrada   : n q, n enteros, luego q consultas: \"1 k u\" (a[k] = u) o \"2 a b\" (mínimo en [a, b])\n * Salida    : el mínimo de cada consulta de tipo 2\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n */\n\n// árbol iterativo: las hojas están en t[n..2n) y cada padre guarda el mínimo de sus hijos\nstruct SegmentTree {\n    int n;\n    vector<ll> t;\n\n    SegmentTree(const vector<ll> &a) {\n        n = a.size();\n        t.assign(2 * n, INF);\n        for (int i = 0; i < n; i++) t[n + i] = a[i];\n        for (int i = n - 1; i > 0; i--) t[i] = min(t[2 * i], t[2 * i + 1]);\n    }\n\n    // se cambia la hoja y se recalcula hacia la raíz\n    void update(int p, ll value) {\n        for (t[p += n] = value; p > 1; p >>= 1) t[p >> 1] = min(t[p], t[p ^ 1]);\n    }\n\n    // mínimo en [l, r)\n    // mínimo en [l, r): se sube juntando los nodos que cubren el rango\n    ll query(int l, int r) {\n        ll res = INF;\n        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {\n            if (l & 1) res = min(res, t[l++]);\n            if (r & 1) res = min(res, t[--r]);\n        }\n        return res;\n    }\n};\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    vector<ll> a(n);\n    for (auto &x : a) cin >> x;\n    SegmentTree Tree(a);\n    while (q--) {\n        int type;\n        cin >> type;\n        if (type == 1) {\n            int k;\n            ll u;\n            cin >> k >> u;\n            Tree.update(k - 1, u);\n        }\n        else {\n            int l, r;\n            cin >> l >> r;\n            cout << Tree.query(l - 1, r) << \"\\n\";\n        }\n    }\n    return 0;\n}\n"}, {"id": "Data-Structures-Algorithms-SparseTable", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/SparseTable.cpp", "nombre": "SparseTable", "algoritmo": "Sparse Table (mínimo de rango en O(1))", "problema": "CSES 1647 - Static Range Minimum Queries (https://cses.fi/problemset/task/1647)", "cses": "https://cses.fi/problemset/task/1647", "entrada": "n q, n enteros, luego q consultas \"a b\"", "salida": "el mínimo de cada rango", "complejidad": "tiempo O(n log n + q), memoria O(n log n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Sparse Table (mínimo de rango en O(1))\n * Problema  : CSES 1647 - Static Range Minimum Queries (https://cses.fi/problemset/task/1647)\n * Entrada   : n q, n enteros, luego q consultas \"a b\"\n * Salida    : el mínimo de cada rango\n * Complejidad: tiempo O(n log n + q), memoria O(n log n)\n */\n\n// st[j][i] = mínimo del rango que empieza en i con longitud 2^j\nstruct SparseTable {\n    int n, LOG;\n    vector<vector<ll>> st;\n\n    SparseTable(const vector<ll> &a) {\n        n = a.size();\n        // cantidad de niveles necesarios\n        LOG = 32 - __builtin_clz(n);\n        st.assign(LOG, vector<ll>(n));\n        st[0] = a;\n        // cada nivel combina dos rangos del nivel anterior\n        for (int j = 1; j < LOG; j++)\n            for (int i = 0; i + (1 << j) <= n; i++)\n                st[j][i] = min(st[j - 1][i], st[j - 1][i + (1 << (j - 1))]);\n    }\n\n    // minimo en el rango [l..r] (0-indexado), O(1)\n    ll query(int l, int r) {\n        // se cubre [l..r] con dos rangos de longitud 2^j que se pueden solapar (válido para el mínimo)\n        int j = 31 - __builtin_clz(r - l + 1);\n        return min(st[j][l], st[j][r - (1 << j) + 1]);\n    }\n};\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    vector<ll> a(n);\n    for (auto &x : a) cin >> x;\n\n    SparseTable table(a);\n    while (q--) {\n        int l, r; cin >> l >> r;\n        l--; r--;\n        cout << table.query(l, r) << \"\\n\";\n    }\n    return 0;\n}\n"}, {"id": "Data-Structures-Algorithms-Stack", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/Stack.cpp", "nombre": "Stack", "algoritmo": "Pila monótona (menor valor anterior)", "problema": "CSES 1645 - Nearest Smaller Values (https://cses.fi/problemset/task/1645)", "cses": "https://cses.fi/problemset/task/1645", "entrada": "n, luego n enteros", "salida": "para cada posición, el índice (base 1) del elemento menor más cercano a la izquierda, o 0", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Pila monótona (menor valor anterior)\n * Problema  : CSES 1645 - Nearest Smaller Values (https://cses.fi/problemset/task/1645)\n * Entrada   : n, luego n enteros\n * Salida    : para cada posición, el índice (base 1) del elemento menor más cercano a la izquierda, o 0\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<ll> a(n);\n    for (auto &x : a) cin >> x;\n\n    // la pila guarda índices con valores estrictamente crecientes\n    // se mantienen los candidatos a \"menor más cercano\"\n    stack<int> st;\n    for (int i = 0; i < n; i++) {\n        // los mayores o iguales a a[i] ya no sirven para elementos futuros\n        while (!st.empty() && a[st.top()] >= a[i]) st.pop();\n        // el tope es el menor más cercano a la izquierda (o 0 si no hay)\n        cout << (st.empty() ? 0 : st.top() + 1) << ' ';\n        // a[i] es candidato para los siguientes\n        st.push(i);\n    }\n    cout << \"\\n\";\n    return 0;\n}\n"}, {"id": "Data-Structures-Algorithms-SweepLine", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/SweepLine.cpp", "nombre": "SweepLine", "algoritmo": "Sweep line (eventos ordenados)", "problema": "CSES 1619 - Restaurant Customers (https://cses.fi/problemset/task/1619)", "cses": "https://cses.fi/problemset/task/1619", "entrada": "n, luego n pares \"llegada salida\"", "salida": "máxima cantidad de clientes simultáneos", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Sweep line (eventos ordenados)\n * Problema  : CSES 1619 - Restaurant Customers (https://cses.fi/problemset/task/1619)\n * Entrada   : n, luego n pares \"llegada salida\"\n * Salida    : máxima cantidad de clientes simultáneos\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    // eventos: +1 al llegar y -1 al salir\n    vector<pair<int, int>> events;  // {tiempo, +1 llega / -1 sale}\n    for (int i = 0; i < n; i++) {\n        int a, b;\n        cin >> a >> b;\n        events.push_back({a, 1});\n        events.push_back({b, -1});\n    }\n    // a igual tiempo, las salidas (-1) van antes que las llegadas\n    sort(all(events));\n\n    int cur = 0, best = 0;\n    for (auto [t, d] : events) {\n        // cur = clientes presentes en este momento\n        cur += d;\n        best = max(best, cur);\n    }\n    cout << best << \"\\n\";\n    return 0;\n}\n"}, {"id": "Data-Structures-Algorithms-TwoPointers", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Algorithms", "archivo": "Data Structures/Algorithms/TwoPointers.cpp", "nombre": "TwoPointers", "algoritmo": "Dos punteros sobre arreglo ordenado (suma de dos valores)", "problema": "CSES 1640 - Sum of Two Values (https://cses.fi/problemset/task/1640)", "cses": "https://cses.fi/problemset/task/1640", "entrada": "n x, luego n enteros", "salida": "dos posiciones (base 1) cuyos valores suman x, o IMPOSSIBLE", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Dos punteros sobre arreglo ordenado (suma de dos valores)\n * Problema  : CSES 1640 - Sum of Two Values (https://cses.fi/problemset/task/1640)\n * Entrada   : n x, luego n enteros\n * Salida    : dos posiciones (base 1) cuyos valores suman x, o IMPOSSIBLE\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    ll x;\n    cin >> n >> x;\n    // se guarda el índice original junto al valor\n    vector<pair<ll, int>> a(n);\n    for (int i = 0; i < n; i++) {\n        cin >> a[i].first;\n        a[i].second = i + 1;\n    }\n    sort(all(a));\n\n    // dos punteros en los extremos del arreglo ordenado\n    int l = 0, r = n - 1;\n    while (l < r) {\n        ll s = a[l].first + a[r].first;\n        if (s == x) {\n            cout << a[l].second << ' ' << a[r].second << \"\\n\";\n            return 0;\n        }\n        // suma pequeña: se sube el menor; suma grande: se baja el mayor\n        if (s < x) l++;\n        else r--;\n    }\n    cout << \"IMPOSSIBLE\\n\";\n    return 0;\n}\n"}, {"id": "Data-Structures-Classic-Problems-K-Smallest-Sums", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Classic Problems", "archivo": "Data Structures/Classic Problems/K-Smallest Sums.cpp", "nombre": "K-Smallest Sums", "algoritmo": "K menores sumas con heap (fusión de dos listas ordenadas)", "problema": "UVa 11997 - K Smallest Sums", "cses": "", "entrada": "varios casos: k, luego k filas de k enteros", "salida": "las k menores sumas posibles (una por columna), por caso", "complejidad": "tiempo O(k^2 log k), memoria O(k)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : K menores sumas con heap (fusión de dos listas ordenadas)\n * Problema  : UVa 11997 - K Smallest Sums\n * Entrada   : varios casos: k, luego k filas de k enteros\n * Salida    : las k menores sumas posibles (una por columna), por caso\n * Complejidad: tiempo O(k^2 log k), memoria O(k)\n */\n\n// comparador para que el heap sea un min-heap por la suma\nclass comp{\n\tpublic:\n\t\tbool operator()(tuple<ll, ll, ll>& a, tuple<ll, ll, ll>&b){\n\t\t\treturn get<0>(a) > get<0>(b);\n\t\t}\n};\n\n// mezcla dos listas ordenadas y devuelve las k menores sumas a[i] + b[j]\nvector<ll> merge(vector<ll> &a, vector<ll> &b, int k){\n\tvector<ll> res(k);\n\n\tpriority_queue<tuple<ll, ll, ll>, vector<tuple<ll, ll, ll>>, comp> heap;\n\tll suma, ii, j;\n\tset<tuple<ll, ll>> vis;\n\t// la menor suma posible es a[0] + b[0]\n\theap.push({a[0] + b[0], 0, 0});\n\tfor(int i = 0; i < k; i++){\n\t\t// se saca la menor suma pendiente\n\t\tauto [suma, ii, j] = heap.top(); heap.pop();\n\t\tres[i] = suma;\n\t\t\n\t\t// se agregan los dos vecinos (i+1, j) y (i, j+1); vis evita repetirlos\n\t\tif(ii+1 < k && vis.find({ii+1, j}) == vis.end()){\n\t\t\ttuple<ll, ll, ll> first = {a[ii+1] + b[j], ii+1, j};\n\t\t\theap.push(first);\n\t\t\tvis.insert({ii+1, j});\n\t\t}\n\t\tif(j+1 < k && vis.find({ii, j+1}) == vis.end()){\n\t\t\ttuple<ll, ll, ll> second = {a[ii] + b[j+1], ii, j+1};\n\t\t\theap.push(second);\n\t\t\tvis.insert({ii, j+1});\n\t\t}\n\n\t}\n\treturn res;\n}\n \nint main(){\n\tfastio;\n\tint k; \n\twhile(cin >> k){\n\t\tvector<ll> res(k); for(auto&x:res){cin >> x;}\n\t\tsort(res.begin(), res.end());\n\t\tfor(int i = 1; i < k; i++){\n\t\t\tvector<ll> a(k); for(auto&x:a){cin >> x;} sort(a.begin(), a.end());\n\t\t\tres = merge(res, a, k); sort(res.begin(), res.end());\n\t\t}\n\t\tfor(int i = 0; i < k-1; i++) cout << res[i] << \" \";\n\t\tcout << res.back() << \"\\n\";\n\t}\n}\n"}, {"id": "Data-Structures-Classic-Problems-Team-Queue", "carpeta": "Data Structures", "area": "Estructuras de datos", "sub": "Classic Problems", "archivo": "Data Structures/Classic Problems/Team Queue.cpp", "nombre": "Team Queue", "algoritmo": "Cola de equipos (cola de colas)", "problema": "UVa 540 - Team Queue", "cses": "", "entrada": "varios casos: n equipos con sus miembros y órdenes ENQUEUE x / DEQUEUE / STOP, terminando con n = 0", "salida": "cada elemento desencolado, bajo \"Scenario #t\"", "complejidad": "tiempo O(1) por operación, memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Cola de equipos (cola de colas)\n * Problema  : UVa 540 - Team Queue\n * Entrada   : varios casos: n equipos con sus miembros y órdenes ENQUEUE x / DEQUEUE / STOP, terminando con n = 0\n * Salida    : cada elemento desencolado, bajo \"Scenario #t\"\n * Complejidad: tiempo O(1) por operación, memoria O(n)\n */\n\nint main(){\n\tfastio;\n\tint tt = 1;\n\twhile(true){\n\t\tll n; cin >> n;\n\t\tif(n == 0) break;\n\t\t\n\t\t// TeamQueue[x] = cola del equipo al que pertenece x\n\t\tmap<ll, queue<ll>*> TeamQueue;\n\t\t// cola de equipos que tienen alguien esperando\n\t\tqueue<queue<ll>*> Queue;\n\n\t\tfor(int i = 0; i < n; i++){\n\t\t\tll k; cin >> k;\n\t\t\tqueue<ll>* team = new queue<ll>();\n\t\t\tfor(int j = 0; j < k; j++){\n\t\t\t\tll x; cin >> x;\n\t\t\t\tTeamQueue[x] = team;\n\t\t\t}\n\t\t}\n\n\t\tcout << \"Scenario #\" << tt << \"\\n\";\n\t\twhile (true)\n\t\t{\n\t\t\tstring s; cin >> s;\n\t\t\t// fin del caso\n\t\t\tif(s == \"STOP\") break;\n\t\t\t// el nuevo entra a la cola de su equipo; si el equipo estaba vacío, el equipo entra al final\n\t\t\telse if(s == \"ENQUEUE\"){\n\t\t\t\tll x; cin >> x;\n\t\t\t\tTeamQueue[x]->push(x);\n\t\t\t\tif(TeamQueue[x]->size() == 1){\n\t\t\t\t\tQueue.push(TeamQueue[x]);\n\t\t\t\t}\n\t\t\t}\n\t\t\telse{\n\t\t\t\t// DEQUEUE: sale el primero del equipo que está al frente\n\t\t\t\tll x = Queue.front()->front();\n\t\t\t\tcout << x << \"\\n\";\n\t\t\t\tQueue.front()->pop();\n\n\t\t\t\t// si el equipo se vacía, deja la cola de equipos\n\t\t\t\tif(Queue.front()->size() == 0) Queue.pop();\n\t\t\t}\n\t\t}\n\t\ttt++; cout << \"\\n\";\n\t}\n}\n"}, {"id": "Graphs-Algorithms-Flow-Algoritms-BipartiteMatching", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Flow Algoritms", "archivo": "Graphs/Algorithms/Flow Algoritms/BipartiteMatching.cpp", "nombre": "BipartiteMatching", "algoritmo": "Emparejamiento bipartito máximo (algoritmo de Kuhn)", "problema": "CSES 1696 - School Dance (https://cses.fi/problemset/task/1696)", "cses": "https://cses.fi/problemset/task/1696", "entrada": "n m k, luego k pares \"chico chica\"", "salida": "cantidad máxima de parejas y las parejas", "complejidad": "tiempo O(V · E), memoria O(V + E)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Emparejamiento bipartito máximo (algoritmo de Kuhn)\n * Problema  : CSES 1696 - School Dance (https://cses.fi/problemset/task/1696)\n * Entrada   : n m k, luego k pares \"chico chica\"\n * Salida    : cantidad máxima de parejas y las parejas\n * Complejidad: tiempo O(V · E), memoria O(V + E)\n */\n\nint n, m;\nvector<vector<int>> G;\n// match[v] = nodo de la izquierda emparejado con v (0 si ninguno)\nvector<int> match;  // match[chica] = chico emparejado (0 si ninguno)\nvector<bool> used;\n\n// busca un camino aumentante desde u\nbool kuhn(int u) {\n    for (int v : G[u]) {\n        if (used[v]) continue;\n        used[v] = true;\n        // v está libre, o se puede reubicar a quien lo ocupa\n        if (match[v] == 0 || kuhn(match[v])) {\n            match[v] = u;\n            return true;\n        }\n    }\n    return false;\n}\n\nint main() {\n    fastio;\n    int k;\n    cin >> n >> m >> k;\n    G.assign(n + 1, {});\n    match.assign(m + 1, 0);\n    for (int i = 0; i < k; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n    }\n\n    int total = 0;\n    // se intenta emparejar a cada nodo de la izquierda\n    for (int u = 1; u <= n; u++) {\n        // used evita visitar un nodo dos veces en la misma búsqueda\n        used.assign(m + 1, false);\n        if (kuhn(u)) total++;\n    }\n\n    cout << total << \"\\n\";\n    for (int v = 1; v <= m; v++)\n        if (match[v]) cout << match[v] << ' ' << v << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Flow-Algoritms-Dinic", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Flow Algoritms", "archivo": "Graphs/Algorithms/Flow Algoritms/Dinic.cpp", "nombre": "Dinic", "algoritmo": "Dinic (flujo máximo)", "problema": "CSES 1694 - Download Speed (https://cses.fi/problemset/task/1694)", "cses": "https://cses.fi/problemset/task/1694", "entrada": "n m, luego m aristas dirigidas \"a b c\" (capacidad c)", "salida": "el flujo máximo de 1 a n", "complejidad": "tiempo O(V^2 · E), memoria O(V + E)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Dinic (flujo máximo)\n * Problema  : CSES 1694 - Download Speed (https://cses.fi/problemset/task/1694)\n * Entrada   : n m, luego m aristas dirigidas \"a b c\" (capacidad c)\n * Salida    : el flujo máximo de 1 a n\n * Complejidad: tiempo O(V^2 · E), memoria O(V + E)\n */\n\n// Dinic: cada fase arma un grafo por niveles (BFS) y envía flujo bloqueante (DFS)\nstruct Dinic {\n    struct Edge {\n        int to;\n        ll cap;\n    };\n    int n;\n    vector<Edge> edges;\n    vector<vector<int>> G;\n    vector<int> level, it;\n\n    Dinic(int n): n(n), G(n + 1), level(n + 1), it(n + 1) {}\n\n    // arista y su inversa (capacidad 0) en posiciones consecutivas: id ^ 1 es la inversa\n    void addEdge(int u, int v, ll cap) {\n        G[u].push_back(edges.size());\n        edges.push_back({v, cap});\n        G[v].push_back(edges.size());\n        edges.push_back({u, 0});\n    }\n\n    // niveles desde s; devuelve si t es alcanzable\n    bool bfs(int s, int t) {\n        fill(all(level), -1);\n        queue<int> q;\n        level[s] = 0;\n        q.push(s);\n        while (!q.empty()) {\n            int u = q.front();\n            q.pop();\n            for (int id : G[u]) {\n                if (edges[id].cap > 0 && level[edges[id].to] == -1) {\n                    level[edges[id].to] = level[u] + 1;\n                    q.push(edges[id].to);\n                }\n            }\n        }\n        return level[t] != -1;\n    }\n\n    // empuja flujo solo por aristas que suben un nivel; it[v] recuerda por dónde seguir\n    ll dfs(int v, int t, ll pushed) {\n        if (v == t || pushed == 0) return pushed;\n        for (int &i = it[v]; i < (int)G[v].size(); i++) {\n            int id = G[v][i];\n            int u = edges[id].to;\n            if (level[u] != level[v] + 1 || edges[id].cap == 0) continue;\n            ll f = dfs(u, t, min(pushed, edges[id].cap));\n            if (f > 0) {\n                edges[id].cap -= f;\n                edges[id ^ 1].cap += f;\n                return f;\n            }\n        }\n        return 0;\n    }\n\n    // mientras exista camino, se repiten fases\n    ll maxflow(int s, int t) {\n        ll flow = 0;\n        while (bfs(s, t)) {\n            fill(all(it), 0);\n            while (ll f = dfs(s, t, INF)) flow += f;\n        }\n        return flow;\n    }\n};\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    Dinic flow(n);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        ll c;\n        cin >> a >> b >> c;\n        flow.addEdge(a, b, c);\n    }\n    cout << flow.maxflow(1, n) << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Flow-Algoritms-EdmonsKarp", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Flow Algoritms", "archivo": "Graphs/Algorithms/Flow Algoritms/EdmonsKarp.cpp", "nombre": "EdmonsKarp", "algoritmo": "Edmonds-Karp (flujo máximo con BFS)", "problema": "CSES 1694 - Download Speed (https://cses.fi/problemset/task/1694)", "cses": "https://cses.fi/problemset/task/1694", "entrada": "n m, luego m aristas dirigidas \"a b c\" (capacidad c)", "salida": "el flujo máximo de 1 a n", "complejidad": "tiempo O(V · E^2), memoria O(V^2)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Edmonds-Karp (flujo máximo con BFS)\n * Problema  : CSES 1694 - Download Speed (https://cses.fi/problemset/task/1694)\n * Entrada   : n m, luego m aristas dirigidas \"a b c\" (capacidad c)\n * Salida    : el flujo máximo de 1 a n\n * Complejidad: tiempo O(V · E^2), memoria O(V^2)\n */\n\nint n;\n// capacity[u][v] = capacidad residual; adj solo para recorrer vecinos\nvector<vector<ll>> capacity;\nvector<vector<int>> adj;\n\n// BFS que busca un camino aumentante; devuelve el cuello de botella\n// BFS que busca un camino aumentante; devuelve el cuello de botella\nll bfs(int s, int t, vector<int> &parent) {\n    fill(all(parent), -1);\n    parent[s] = -2;\n    queue<pair<int, ll>> q;\n    q.push({s, INF});\n    while (!q.empty()) {\n        auto [u, flow] = q.front();\n        q.pop();\n        for (int v : adj[u]) {\n            if (parent[v] == -1 && capacity[u][v] > 0) {\n                parent[v] = u;\n                ll new_flow = min(flow, capacity[u][v]);\n                if (v == t) return new_flow;\n                q.push({v, new_flow});\n            }\n        }\n    }\n    return 0;\n}\n\n// se aumenta el flujo mientras haya camino\nll maxflow(int s, int t) {\n    ll flow = 0;\n    vector<int> parent(n + 1);\n    while (ll new_flow = bfs(s, t, parent)) {\n        flow += new_flow;\n        int cur = t;\n        while (cur != s) {\n            int prev = parent[cur];\n            // se resta en la arista y se suma en la inversa\n            capacity[prev][cur] -= new_flow;\n            capacity[cur][prev] += new_flow;\n            cur = prev;\n        }\n    }\n    return flow;\n}\n\nint main() {\n    fastio;\n    int m;\n    cin >> n >> m;\n    capacity.assign(n + 1, vector<ll>(n + 1, 0));\n    adj.assign(n + 1, {});\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        ll c;\n        cin >> a >> b >> c;\n        if (capacity[a][b] == 0 && capacity[b][a] == 0) {\n            adj[a].push_back(b);\n            adj[b].push_back(a);\n        }\n        // se suman capacidades si hay aristas repetidas\n        capacity[a][b] += c;\n    }\n    cout << maxflow(1, n) << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Flow-Algoritms-MinCostAnyFlow", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Flow Algoritms", "archivo": "Graphs/Algorithms/Flow Algoritms/MinCostAnyFlow.cpp", "nombre": "MinCostAnyFlow", "algoritmo": "Flujo de costo mínimo con exactamente K unidades (Successive Shortest Paths)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "entrada": "n m K, luego m aristas \"u v cap cost\" (nodos 1..n, fuente 1, sumidero n)", "salida": "IMPOSSIBLE si no se pueden enviar K unidades; si no, el costo mínimo", "complejidad": "tiempo O(K · E log V), memoria O(V + E)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Flujo de costo mínimo con exactamente K unidades (Successive Shortest Paths)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n m K, luego m aristas \"u v cap cost\" (nodos 1..n, fuente 1, sumidero n)\n * Salida    : IMPOSSIBLE si no se pueden enviar K unidades; si no, el costo mínimo\n * Complejidad: tiempo O(K · E log V), memoria O(V + E)\n */\n\n// cada arista guarda destino, índice de su inversa, capacidad y costo\nstruct MinCostFlow {\n    struct Edge { ll to, rev, cap, cost; };\n    \n    ll n;\n    vector<vector<Edge>> adj;\n    \n    MinCostFlow(ll n=0): n(n), adj(n) {}\n\n    // agrega la arista y su inversa (capacidad 0 y costo negativo)\n    ll add_edge(ll u, ll v, ll cap, ll cost){\n        ll iu = adj[u].size();\n        ll iv = adj[v].size();\n        adj[u].push_back({v, iv, cap, cost});\n        adj[v].push_back({u, iu, 0, -cost});\n        return iu;\n    }\n\n    // try to send exactly K flow from s to t; returns {flow_sent, total_cost}\n    pair<ll,ll> min_cost_flow_k(ll s, ll t, ll K){\n        ll flow = 0, cost = 0;\n        vector<ll> potential(n, 0), dist(n);\n        vector<ll> parent_vertex(n), parent_edge(n);\n\n        // init potentials with Bellman-Ford if negative edges exist (safe)\n        for(int it = 0; it < n; ++it){\n            bool any = false;\n            for(int v = 0; v < n; ++v){\n                if(potential[v] == INF) continue;\n                for(auto &edge : adj[v]){\n                    if(edge.cap > 0 && potential[edge.to] > potential[v] + edge.cost){\n                        potential[edge.to] = potential[v] + edge.cost;\n                        any = true;\n                    }\n                }\n            }\n            if(!any) break;\n        }\n\n        // cada vuelta envía flujo por el camino más barato del grafo residual (Dijkstra con potenciales)\n        while(flow < K){\n            fill(all(dist), INF); dist[s] = 0;\n\n            priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;\n            pq.push({0, s});\n            \n            while(!pq.empty()){\n                auto [dis, v] = pq.top(); pq.pop();\n                if(dis != dist[v]) continue;\n                for(int i = 0; i < (int)adj[v].size(); ++i){\n                    auto &edge = adj[v][i];\n                    if(edge.cap <= 0) continue;\n                    ll new_dis = dis + edge.cost + potential[v] - potential[edge.to];\n                    if(new_dis < dist[edge.to]){\n                        dist[edge.to] = new_dis;\n                        parent_vertex[edge.to] = v;\n                        parent_edge[edge.to] = i;\n                        pq.push({new_dis, edge.to});\n                    }\n                }\n            }\n            if(dist[t] == INF) break; // cannot send more\n\n            for(int v = 0; v < n; ++v)\n                if(dist[v] < INF) potential[v] += dist[v];\n\n            // cuello de botella del camino encontrado\n            ll add = K - flow;\n            int v = t;\n            while(v != s){\n                auto &edge = adj[parent_vertex[v]][parent_edge[v]];\n                add = min(add, edge.cap);\n                v = parent_vertex[v];\n            }\n\n            v = t;\n            while(v != s){\n                auto &edge = adj[parent_vertex[v]][parent_edge[v]];\n                edge.cap -= add;\n                adj[v][edge.rev].cap += add;\n                v = parent_vertex[v];\n            }\n\n            // potential[t] es el costo real del camino más corto\n            flow += add;\n            cost += add * potential[t]; // potential[t] equals actual shortest path cost\n        }\n\n        return {flow, cost};\n    }\n};\n\nint main() {\n    fastio;\n    int n, m;\n    ll K;\n    cin >> n >> m >> K;\n    MinCostFlow mcf(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        ll cap, cost;\n        cin >> u >> v >> cap >> cost;\n        mcf.add_edge(u, v, cap, cost);\n    }\n\n    auto [flow, cost] = mcf.min_cost_flow_k(1, n, K);\n    if (flow < K) cout << \"IMPOSSIBLE\\n\";\n    else cout << cost << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Flow-Algoritms-MinCostMaxFlow", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Flow Algoritms", "archivo": "Graphs/Algorithms/Flow Algoritms/MinCostMaxFlow.cpp", "nombre": "MinCostMaxFlow", "algoritmo": "Flujo máximo de costo mínimo (Successive Shortest Paths con potenciales)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "entrada": "n m, luego m aristas \"u v cap cost\" (nodos 1..n, fuente 1, sumidero n)", "salida": "cantidad de flujo máximo enviado y su costo mínimo total", "complejidad": "tiempo O(F · E log V), F = flujo total, memoria O(V + E)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Flujo máximo de costo mínimo (Successive Shortest Paths con potenciales)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n m, luego m aristas \"u v cap cost\" (nodos 1..n, fuente 1, sumidero n)\n * Salida    : cantidad de flujo máximo enviado y su costo mínimo total\n * Complejidad: tiempo O(F · E log V), F = flujo total, memoria O(V + E)\n */\n\n// cada arista guarda destino, índice de su inversa, capacidad y costo\nstruct MinCostFlow {\n    struct Edge { ll to, rev, cap, cost; };\n    \n    ll n;\n    vector<vector<Edge>> adj;\n    \n    MinCostFlow(ll n=0): n(n), adj(n) {}\n\n    // agrega la arista y su inversa (capacidad 0 y costo negativo)\n    ll add_edge(ll u, ll v, ll cap, ll cost){\n        ll iu = adj[u].size();\n        ll iv = adj[v].size();\n        adj[u].push_back({v, iv, cap, cost});\n        adj[v].push_back({u, iu, 0, -cost});\n        return iu;\n    }\n\n    // try to send exactly K flow from s to t; returns {flow_sent, total_cost}\n    pair<ll,ll> min_cost_flow_k(ll s, ll t, ll K){\n        ll flow = 0, cost = 0;\n        vector<ll> potential(n, 0), dist(n);\n        vector<ll> parent_vertex(n), parent_edge(n);\n\n        // init potentials with Bellman-Ford if negative edges exist (safe)\n        for(int it = 0; it < n; ++it){\n            bool any = false;\n            for(int v = 0; v < n; ++v){\n                if(potential[v] == INF) continue;\n                for(auto &edge : adj[v]){\n                    if(edge.cap > 0 && potential[edge.to] > potential[v] + edge.cost){\n                        potential[edge.to] = potential[v] + edge.cost;\n                        any = true;\n                    }\n                }\n            }\n            if(!any) break;\n        }\n\n        // cada vuelta envía flujo por el camino más barato del grafo residual (Dijkstra con potenciales)\n        while(flow < K){\n            fill(all(dist), INF); dist[s] = 0;\n\n            priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;\n            pq.push({0, s});\n            \n            while(!pq.empty()){\n                auto [dis, v] = pq.top(); pq.pop();\n                if(dis != dist[v]) continue;\n                for(int i = 0; i < (int)adj[v].size(); ++i){\n                    auto &edge = adj[v][i];\n                    if(edge.cap <= 0) continue;\n                    ll new_dis = dis + edge.cost + potential[v] - potential[edge.to];\n                    if(new_dis < dist[edge.to]){\n                        dist[edge.to] = new_dis;\n                        parent_vertex[edge.to] = v;\n                        parent_edge[edge.to] = i;\n                        pq.push({new_dis, edge.to});\n                    }\n                }\n            }\n            if(dist[t] == INF) break; // cannot send more\n\n            for(int v = 0; v < n; ++v)\n                if(dist[v] < INF) potential[v] += dist[v];\n\n            // cuello de botella del camino encontrado\n            ll add = K - flow;\n            int v = t;\n            while(v != s){\n                auto &edge = adj[parent_vertex[v]][parent_edge[v]];\n                add = min(add, edge.cap);\n                v = parent_vertex[v];\n            }\n\n            v = t;\n            while(v != s){\n                auto &edge = adj[parent_vertex[v]][parent_edge[v]];\n                edge.cap -= add;\n                adj[v][edge.rev].cap += add;\n                v = parent_vertex[v];\n            }\n\n            // potential[t] es el costo real del camino más corto\n            flow += add;\n            cost += add * potential[t]; // potential[t] equals actual shortest path cost\n        }\n\n        return {flow, cost};\n    }\n};\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    MinCostFlow mcf(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        ll cap, cost;\n        cin >> u >> v >> cap >> cost;\n        mcf.add_edge(u, v, cap, cost);\n    }\n\n    // K = INF: se envía todo el flujo posible\n    auto [flow, cost] = mcf.min_cost_flow_k(1, n, INF);\n    cout << flow << ' ' << cost << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-BFS", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/BFS.cpp", "nombre": "BFS", "algoritmo": "BFS (camino más corto en grafo no ponderado)", "problema": "CSES 1667 - Message Route (https://cses.fi/problemset/task/1667)", "cses": "https://cses.fi/problemset/task/1667", "entrada": "n m, luego m aristas \"a b\"", "salida": "IMPOSSIBLE, o la cantidad de nodos y un camino mínimo de 1 a n", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : BFS (camino más corto en grafo no ponderado)\n * Problema  : CSES 1667 - Message Route (https://cses.fi/problemset/task/1667)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : IMPOSSIBLE, o la cantidad de nodos y un camino mínimo de 1 a n\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> G(n + 1);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        G[b].push_back(a);\n    }\n\n    // dist[v] = aristas desde 1, parent[v] = nodo anterior en el camino mínimo\n    vector<int> dist(n + 1, -1), parent(n + 1, 0);\n    queue<int> q;\n    dist[1] = 0;\n    q.push(1);\n    // BFS: visita por capas, así la primera vez que se llega a un nodo es por el camino más corto\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n        for (int v : G[u]) {\n            if (dist[v] != -1) continue;\n            dist[v] = dist[u] + 1;\n            parent[v] = u;\n            q.push(v);\n        }\n    }\n\n    if (dist[n] == -1) {\n        cout << \"IMPOSSIBLE\\n\";\n        return 0;\n    }\n    // se reconstruye el camino desde n hasta 1 con parent[]\n    vector<int> path;\n    for (int v = n; v != 0; v = parent[v]) path.push_back(v);\n    reverse(all(path));\n    cout << path.size() << \"\\n\";\n    for (int v : path) cout << v << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-BellmanFord", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/BellmanFord.cpp", "nombre": "BellmanFord", "algoritmo": "Bellman-Ford (detección de ciclo negativo)", "problema": "CSES 1197 - Cycle Finding (https://cses.fi/problemset/task/1197)", "cses": "https://cses.fi/problemset/task/1197", "entrada": "n m, luego m aristas dirigidas \"a b c\" (peso c)", "salida": "NO, o YES y un ciclo de peso negativo", "complejidad": "tiempo O(n·m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Bellman-Ford (detección de ciclo negativo)\n * Problema  : CSES 1197 - Cycle Finding (https://cses.fi/problemset/task/1197)\n * Entrada   : n m, luego m aristas dirigidas \"a b c\" (peso c)\n * Salida    : NO, o YES y un ciclo de peso negativo\n * Complejidad: tiempo O(n·m), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    // aristas {a, b, c}\n    vector<array<ll, 3>> edges(m);\n    for (auto &e : edges) cin >> e[0] >> e[1] >> e[2];\n\n    // dist = 0 para todos: equivale a un nodo fuente virtual conectado a todos\n    // dist = 0 para todos: equivale a un nodo fuente virtual conectado a todos\n    vector<ll> dist(n + 1, 0);\n    vector<int> parent(n + 1, 0);\n    int last = -1;\n    // n rondas de relajación; si en la n-ésima aún mejora, hay ciclo negativo\n    for (int i = 0; i < n; i++) {\n        last = -1;\n        for (auto &[a, b, c] : edges) {\n            if (dist[a] + c < dist[b]) {\n                dist[b] = dist[a] + c;\n                parent[b] = a;\n                last = b;\n            }\n        }\n        if (last == -1) break;\n    }\n\n    if (last == -1) {\n        cout << \"NO\\n\";\n        return 0;\n    }\n    // retroceder n veces para asegurar estar dentro del ciclo\n    // retroceder n veces para asegurar estar dentro del ciclo\n    for (int i = 0; i < n; i++) last = parent[last];\n    // se recorre el ciclo siguiendo parent[] hasta volver a last\n    vector<int> cycle;\n    for (int v = last;; v = parent[v]) {\n        cycle.push_back(v);\n        if (v == last && cycle.size() > 1) break;\n    }\n    reverse(all(cycle));\n    cout << \"YES\\n\";\n    for (int v : cycle) cout << v << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-Bipartite", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/Bipartite.cpp", "nombre": "Bipartite", "algoritmo": "Grafo bipartito (coloreo con BFS)", "problema": "CSES 1668 - Building Teams (https://cses.fi/problemset/task/1668)", "cses": "https://cses.fi/problemset/task/1668", "entrada": "n m, luego m aristas \"a b\"", "salida": "IMPOSSIBLE, o el equipo (1 o 2) de cada nodo", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Grafo bipartito (coloreo con BFS)\n * Problema  : CSES 1668 - Building Teams (https://cses.fi/problemset/task/1668)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : IMPOSSIBLE, o el equipo (1 o 2) de cada nodo\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> G(n + 1);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        G[b].push_back(a);\n    }\n\n    // color 1 o 2 por nodo (0 = aún sin color)\n    vector<int> color(n + 1, 0);  // 0 = sin color\n    for (int s = 1; s <= n; s++) {\n        if (color[s]) continue;\n        // cada componente se colorea desde un nodo cualquiera\n        color[s] = 1;\n        queue<int> q;\n        q.push(s);\n        while (!q.empty()) {\n            int u = q.front();\n            q.pop();\n            for (int v : G[u]) {\n                if (color[v] == 0) {\n                    // los vecinos reciben el color opuesto\n                    color[v] = 3 - color[u];\n                    q.push(v);\n                }\n                // dos vecinos del mismo color: hay un ciclo impar, no es bipartito\n                else if (color[v] == color[u]) {\n                    cout << \"IMPOSSIBLE\\n\";\n                    return 0;\n                }\n            }\n        }\n    }\n\n    for (int i = 1; i <= n; i++) cout << color[i] << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-DFS", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/DFS.cpp", "nombre": "DFS", "algoritmo": "DFS (componentes conexas)", "problema": "CSES 1666 - Building Roads (https://cses.fi/problemset/task/1666)", "cses": "https://cses.fi/problemset/task/1666", "entrada": "n m, luego m aristas \"a b\"", "salida": "cantidad mínima de caminos a construir y las aristas que conectan las componentes", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : DFS (componentes conexas)\n * Problema  : CSES 1666 - Building Roads (https://cses.fi/problemset/task/1666)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : cantidad mínima de caminos a construir y las aristas que conectan las componentes\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// visited[u] indica si u ya fue explorado\nvector<vector<int>> G;\nvector<bool> visited;\n\n// explora toda la componente de u\nvoid dfs(int u) {\n    visited[u] = true;\n    for (int v : G[u])\n        if (!visited[v]) dfs(v);\n}\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    G.assign(n + 1, {});\n    visited.assign(n + 1, false);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        G[b].push_back(a);\n    }\n\n    // un representante por componente; se unen en cadena\n    // un representante por cada componente conexa\n    vector<int> reps;\n    for (int i = 1; i <= n; i++) {\n        if (!visited[i]) {\n            reps.push_back(i);\n            dfs(i);\n        }\n    }\n\n    // se necesitan (componentes - 1) caminos para unirlas\n    cout << reps.size() - 1 << \"\\n\";\n    for (int i = 1; i < (int)reps.size(); i++)\n        cout << reps[i - 1] << ' ' << reps[i] << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-DSU", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/DSU.cpp", "nombre": "DSU", "algoritmo": "DSU (Union-Find con compresión de caminos y unión por tamaño)", "problema": "CSES 1676 - Road Construction (https://cses.fi/problemset/task/1676)", "cses": "https://cses.fi/problemset/task/1676", "entrada": "n m, luego m aristas \"a b\"", "salida": "tras cada arista: cantidad de componentes y tamaño de la componente más grande", "complejidad": "tiempo O(m α(n)), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : DSU (Union-Find con compresión de caminos y unión por tamaño)\n * Problema  : CSES 1676 - Road Construction (https://cses.fi/problemset/task/1676)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : tras cada arista: cantidad de componentes y tamaño de la componente más grande\n * Complejidad: tiempo O(m α(n)), memoria O(n)\n */\n\n// Union-Find: parent[x] es el padre en el bosque y size el tamaño de cada conjunto\nstruct DSU {\n    vector<int> parent, size;\n\n    DSU(int n) {\n        parent.resize(n + 1);\n        size.assign(n + 1, 1);\n        iota(all(parent), 0);\n    }\n\n    // compresión de caminos\n    int find(int x) {\n        return parent[x] == x ? x : parent[x] = find(parent[x]);\n    }\n\n    // unión por tamaño: el conjunto pequeño se cuelga del grande\n    bool unite(int a, int b) {\n        a = find(a), b = find(b);\n        if (a == b) return false;\n        if (size[a] < size[b]) swap(a, b);\n        parent[b] = a;\n        size[a] += size[b];\n        return true;\n    }\n};\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    DSU dsu(n);\n    // comps = componentes actuales, biggest = tamaño de la mayor\n    int comps = n, biggest = 1;\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        if (dsu.unite(a, b)) {\n            comps--;\n            biggest = max(biggest, dsu.size[dsu.find(a)]);\n        }\n        cout << comps << ' ' << biggest << \"\\n\";\n    }\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-Diameter", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/Diameter.cpp", "nombre": "Diameter", "algoritmo": "Diámetro de un árbol (dos DFS)", "problema": "CSES 1131 - Tree Diameter (https://cses.fi/problemset/task/1131)", "cses": "https://cses.fi/problemset/task/1131", "entrada": "n, luego n-1 aristas \"a b\"", "salida": "longitud del diámetro (en aristas)", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Diámetro de un árbol (dos DFS)\n * Problema  : CSES 1131 - Tree Diameter (https://cses.fi/problemset/task/1131)\n * Entrada   : n, luego n-1 aristas \"a b\"\n * Salida    : longitud del diámetro (en aristas)\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\n// árbol como lista de adyacencia; dist_dfs[v] = distancia desde la raíz de la DFS actual\nvector<vector<int>> g;\nvector<int> dist_dfs;\n\n// DFS que devuelve el nodo más lejano y su distancia\npair<int,int> dfs_far(int u, int p) {\n    // retorna {nodo más lejano, distancia a él}\n    pair<int,int> best = {u, dist_dfs[u]};\n    for (int v : g[u]) if (v != p) {\n        dist_dfs[v] = dist_dfs[u] + 1;\n        auto cand = dfs_far(v, u);\n        if (cand.second > best.second) best = cand;\n    }\n    return best;\n}\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    g.assign(n+1, {});\n    for (int i = 0; i < n-1; ++i) {\n        int u, v;\n        cin >> u >> v;\n        g[u].push_back(v);\n        g[v].push_back(u);\n    }\n\n    dist_dfs.assign(n+1, 0);\n    // 1ª DFS: desde 1 para hallar vértice A más lejano\n    // el nodo más lejano de cualquier nodo es un extremo del diámetro\n    auto a = dfs_far(1, 0).first;\n\n    // 2ª DFS: desde A para hallar distancia máxima (diámetro)\n    dist_dfs.assign(n+1, 0);\n    // la mayor distancia desde ese extremo es el diámetro\n    auto b = dfs_far(a, 0);\n    cout << b.second << \"\\n\";\n\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-Djikstra", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/Djikstra.cpp", "nombre": "Djikstra", "algoritmo": "Dijkstra con cola de prioridad", "problema": "CSES 1671 - Shortest Routes I (https://cses.fi/problemset/task/1671)", "cses": "https://cses.fi/problemset/task/1671", "entrada": "n m, luego m aristas dirigidas \"a b c\" (peso c)", "salida": "la distancia mínima de 1 a cada nodo", "complejidad": "tiempo O((n + m) log n), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Dijkstra con cola de prioridad\n * Problema  : CSES 1671 - Shortest Routes I (https://cses.fi/problemset/task/1671)\n * Entrada   : n m, luego m aristas dirigidas \"a b c\" (peso c)\n * Salida    : la distancia mínima de 1 a cada nodo\n * Complejidad: tiempo O((n + m) log n), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<vector<pair<int, ll>>> G(n + 1);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        ll c;\n        cin >> a >> b >> c;\n        G[a].push_back({b, c});\n    }\n\n    // dist[v] = mejor distancia conocida desde 1\n    vector<ll> dist(n + 1, INF);\n    // min-heap de {distancia, nodo}\n    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;\n    dist[1] = 0;\n    pq.push({0, 1});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top();\n        pq.pop();\n        // entrada vieja del heap: ya hay una distancia mejor\n        if (d > dist[u]) continue;\n        for (auto [v, w] : G[u]) {\n            // relajación de la arista u -> v\n            if (dist[u] + w < dist[v]) {\n                dist[v] = dist[u] + w;\n                pq.push({dist[v], v});\n            }\n        }\n    }\n\n    for (int i = 1; i <= n; i++) cout << dist[i] << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-EulerianCycle", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/EulerianCycle.cpp", "nombre": "EulerianCycle", "algoritmo": "Ciclo euleriano (Hierholzer, grafo no dirigido)", "problema": "CSES 1691 - Mail Delivery (https://cses.fi/problemset/task/1691)", "cses": "https://cses.fi/problemset/task/1691", "entrada": "n m, luego m aristas \"a b\"", "salida": "un ciclo euleriano desde el nodo 1, o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Ciclo euleriano (Hierholzer, grafo no dirigido)\n * Problema  : CSES 1691 - Mail Delivery (https://cses.fi/problemset/task/1691)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : un ciclo euleriano desde el nodo 1, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// cada arista guarda su destino y un id para marcarla como usada\nstruct Edge{\n    ll to, id;\n};\n\nint main(){\n    fastio;\n\n    ll n, m; cin >> n >> m;\n    // lista de adyacencia; used[id] indica si la arista ya se recorrió\n    vector<vector<Edge>> ady(n, vector<Edge>());\n    vector<bool> used(m, false);\n\n    for(int i = 0; i < m; i++){\n        ll u, v; cin >> u >> v;\n        u--; v--;\n        ady[u].push_back({v, i});\n        ady[v].push_back({u, i});\n    }\n\n    // cycle = circuito resultante (se arma al desapilar)\n    vector<ll> cycle;\n    vector<bool> vis(n, false);\n    // primero se verifica que todos los nodos con aristas sean alcanzables desde 0\n    stack<ll> ss; ss.push(0);\n\n    while (!ss.empty())\n    {\n        ll v = ss.top(); ss.pop();\n        for(auto [u, i]: ady[v]){\n            if(!vis[u]) ss.push(u);\n        }\n        vis[v] = true;\n    }\n\n    // condición de Euler: todos los grados pares y un solo componente conexo\n    bool agg = true;\n    for(int i = 0; i < n; i++){\n        if(ady[i].size() == 0) vis[i] = true;\n        else if(ady[i].size() & 1) agg = false;\n\n        if(vis[i] == false) agg = false;\n    }\n    \n    // si no se cumple la condición no existe el ciclo\n    if(!agg){\n        cout << \"IMPOSSIBLE\" << \"\\n\";\n        return 0;\n    }\n\n    ss.push(0);\n    // Hierholzer iterativo: se avanza por aristas libres y se desapila al quedar sin salida\n    while (!ss.empty()){\n        ll v = ss.top();\n        // se descartan aristas ya usadas desde el otro extremo\n        while (!ady[v].empty() && used[ady[v].back().id]) ady[v].pop_back();\n        \n        if(!ady[v].empty()){\n            auto edge = ady[v].back(); ady[v].pop_back();\n            used[edge.id] = true;\n            ss.push(edge.to);\n        }\n        else{\n            // nodo sin salidas: entra al circuito (queda en orden inverso, válido por ser un ciclo)\n            cycle.push_back(v);\n            ss.pop();\n        }\n    }\n    \n    for(auto &x: cycle) cout << x+1 << \" \";\n    cout << \"\\n\";\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-FloydWarshall", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/FloydWarshall.cpp", "nombre": "FloydWarshall", "algoritmo": "Floyd-Warshall (distancias entre todos los pares)", "problema": "CSES 1672 - Shortest Routes II (https://cses.fi/problemset/task/1672)", "cses": "https://cses.fi/problemset/task/1672", "entrada": "n m q, luego m aristas no dirigidas \"a b c\" y q consultas \"a b\"", "salida": "la distancia mínima de cada consulta, o -1 si no hay camino", "complejidad": "tiempo O(n^3 + q), memoria O(n^2)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Floyd-Warshall (distancias entre todos los pares)\n * Problema  : CSES 1672 - Shortest Routes II (https://cses.fi/problemset/task/1672)\n * Entrada   : n m q, luego m aristas no dirigidas \"a b c\" y q consultas \"a b\"\n * Salida    : la distancia mínima de cada consulta, o -1 si no hay camino\n * Complejidad: tiempo O(n^3 + q), memoria O(n^2)\n */\n\nint main() {\n    fastio;\n    int n, m, q;\n    cin >> n >> m >> q;\n    // inf = INF / 4 para que dist[i][k] + dist[k][j] no desborde\n    const ll inf = INF / 4;  // evita overflow al sumar\n    vector<vector<ll>> dist(n + 1, vector<ll>(n + 1, inf));\n    for (int i = 1; i <= n; i++) dist[i][i] = 0;\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        ll c;\n        cin >> a >> b >> c;\n        dist[a][b] = min(dist[a][b], c);\n        dist[b][a] = min(dist[b][a], c);\n    }\n\n    // k = nodo intermedio permitido: se prueba pasar por k para cada par (i, j)\n    for (int k = 1; k <= n; k++)\n        for (int i = 1; i <= n; i++)\n            for (int j = 1; j <= n; j++)\n                if (dist[i][k] + dist[k][j] < dist[i][j])\n                    dist[i][j] = dist[i][k] + dist[k][j];\n\n    while (q--) {\n        int a, b;\n        cin >> a >> b;\n        cout << (dist[a][b] >= inf ? -1 : dist[a][b]) << \"\\n\";\n    }\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-HierholzerDirected", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/HierholzerDirected.cpp", "nombre": "HierholzerDirected", "algoritmo": "Camino euleriano en grafo dirigido (Hierholzer)", "problema": "CSES 1693 - Teleporters Path (https://cses.fi/problemset/task/1693)", "cses": "https://cses.fi/problemset/task/1693", "entrada": "n m, luego m aristas dirigidas \"a b\"", "salida": "un camino de 1 a n que usa cada arista exactamente una vez, o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Camino euleriano en grafo dirigido (Hierholzer)\n * Problema  : CSES 1693 - Teleporters Path (https://cses.fi/problemset/task/1693)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : un camino de 1 a n que usa cada arista exactamente una vez, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> G(n + 1);\n    // grados de entrada y salida de cada nodo\n    vector<int> in(n + 1, 0), out(n + 1, 0);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        out[a]++, in[b]++;\n    }\n\n    // condiciones del camino de 1 a n\n    // el camino de 1 a n existe si out(1) = in(1) + 1, in(n) = out(n) + 1 y los demás grados coinciden\n    bool ok = out[1] - in[1] == 1 && in[n] - out[n] == 1;\n    for (int i = 2; i < n; i++) ok &= in[i] == out[i];\n    if (!ok) {\n        cout << \"IMPOSSIBLE\\n\";\n        return 0;\n    }\n\n    // Hierholzer iterativo\n    vector<int> path, st = {1};\n    while (!st.empty()) {\n        int u = st.back();\n        if (G[u].empty()) {\n            path.push_back(u);\n            st.pop_back();\n        }\n        else {\n            int v = G[u].back();\n            G[u].pop_back();\n            st.push_back(v);\n        }\n    }\n    reverse(all(path));\n\n    // si no se usaron las m aristas, el grafo no es conexo\n    if ((int)path.size() != m + 1 || path[0] != 1 || path.back() != n) {\n        cout << \"IMPOSSIBLE\\n\";\n        return 0;\n    }\n    for (int v : path) cout << v << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-Kosaraju", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/Kosaraju.cpp", "nombre": "Kosaraju", "algoritmo": "Kosaraju (componentes fuertemente conexas)", "problema": "CSES 1683 - Planets and Kingdoms (https://cses.fi/problemset/task/1683)", "cses": "https://cses.fi/problemset/task/1683", "entrada": "n m, luego m aristas dirigidas \"a b\"", "salida": "cantidad de reinos (SCC) y el reino de cada nodo", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Kosaraju (componentes fuertemente conexas)\n * Problema  : CSES 1683 - Planets and Kingdoms (https://cses.fi/problemset/task/1683)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : cantidad de reinos (SCC) y el reino de cada nodo\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// G = grafo y GT = grafo con las aristas invertidas\nvector<vector<int>> G, GT;\nvector<int> order, comp;\nvector<bool> visited;\n\n// primera pasada: se guarda el orden de salida de cada nodo\nvoid dfs1(int u) {\n    visited[u] = true;\n    for (int v : G[u])\n        if (!visited[v]) dfs1(v);\n    order.push_back(u);  // orden de salida\n}\n\n// segunda pasada sobre GT: todo lo alcanzado forma una SCC\nvoid dfs2(int u, int c) {\n    comp[u] = c;\n    for (int v : GT[u])\n        if (comp[v] == 0) dfs2(v, c);\n}\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    G.assign(n + 1, {});\n    GT.assign(n + 1, {});\n    visited.assign(n + 1, false);\n    comp.assign(n + 1, 0);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        GT[b].push_back(a);\n    }\n\n    for (int i = 1; i <= n; i++)\n        if (!visited[i]) dfs1(i);\n\n    // segunda pasada sobre el grafo transpuesto en orden de salida inverso\n    int c = 0;\n    // se procesan los nodos en orden de salida decreciente\n    for (int i = n - 1; i >= 0; i--)\n        if (comp[order[i]] == 0) dfs2(order[i], ++c);\n\n    cout << c << \"\\n\";\n    for (int i = 1; i <= n; i++) cout << comp[i] << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-Tarjan", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/Tarjan.cpp", "nombre": "Tarjan", "algoritmo": "Componentes fuertemente conexas (Tarjan)", "problema": "CSES 1682 - Flight Routes Check (https://cses.fi/problemset/task/1682)", "cses": "https://cses.fi/problemset/task/1682", "entrada": "n m, luego m aristas dirigidas \"a b\"", "salida": "YES si todo nodo llega a todo nodo; si no, NO y un par \"a b\" sin camino de a hacia b", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Componentes fuertemente conexas (Tarjan)\n * Problema  : CSES 1682 - Flight Routes Check (https://cses.fi/problemset/task/1682)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : YES si todo nodo llega a todo nodo; si no, NO y un par \"a b\" sin camino de a hacia b\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// Tarjan: componentes fuertemente conexas (SCC) con una sola DFS\nstruct Tarjan{\n    // tempo = contador de descubrimiento\n    ll tempo = 0;\n    vector<vector<ll>> ady;\n    // discovered[v] = momento en que se visitó v, low[v] = menor tiempo alcanzable desde su subárbol\n    vector<ll> discovered;\n    vector<ll> low;\n    // pila de nodos de la SCC actual; in_stack evita usar aristas hacia SCC ya cerradas\n    stack<ll> ss;\n    vector<bool> in_stack;\n    // SCC = lista de componentes, SCC_index[v] = componente de v\n    vector<vector<ll>> SCC;\n    vector<ll> SCC_index;\n \n    Tarjan(ll n){\n        ady.assign(n, vector<ll>());\n        discovered.assign(n, -1);\n        low.assign(n, -1);\n        in_stack.assign(n, false);\n        SCC_index.assign(n, -1);\n    }\n \n    void add_edge(ll u, ll v){\n        ady[u].push_back(v);\n    }\n \n    // DFS de Tarjan\n    void DFS(ll v){\n        discovered[v] = tempo;\n        low[v] = tempo;\n        tempo++;\n \n        ss.push(v);\n        in_stack[v] = true;\n \n        for(auto u: ady[v]){\n            // arista de árbol: se baja y se actualiza low con el hijo\n            if(discovered[u] == -1){\n                DFS(u);\n                low[v] = min(low[v], low[u]);\n            }\n            // arista hacia atrás dentro de la misma componente\n            else if(in_stack[u]){\n                low[v] = min(low[v], discovered[u]);\n            }\n        }\n \n        // v es la raíz de una SCC: se desapila hasta v\n        if(low[v] == discovered[v]){\n            vector<ll> newSCC;\n            ll w;\n            do {\n                w = ss.top(); ss.pop();\n                SCC_index[w] = SCC.size();\n                newSCC.push_back(w);\n                in_stack[w] = false;\n            } while (w != v);\n            SCC.push_back(newSCC);\n        }\n    }\n};\n \nint main(){\n    fastio;\n    \n    ll n, m; cin >> n >> m;\n    Tarjan tarjan(n);\n \n    for(int i = 0; i < m; i++){\n        ll u, v; cin >> u >> v;\n        u--; v--;\n        tarjan.add_edge(u, v);\n    }\n \n    for(int i = 0; i < n; i++){\n        if(tarjan.discovered[i] == -1){\n            tarjan.DFS(i);\n        }\n    }\n \n    // una sola SCC = fuertemente conexo\n    if(tarjan.SCC.size() == 1){\n        cout << \"YES\" << \"\\n\";\n    }\n    else{\n        // hay que mostrar un par (a, b) tal que no se pueda ir de a a b\n        cout << \"NO\" << \"\\n\";\n        for(int i = 0; i < n; i++){\n            for(auto j: tarjan.ady[i]){\n                // una arista i->j entre componentes distintas: no existe camino de j a i\n                if(tarjan.SCC_index[i] != tarjan.SCC_index[j]){\n                    cout << j+1 << \" \" << i+1 << \"\\n\";\n                    return 0;\n                }\n            }\n        }\n \n        for(int i = 0; i < n; i++){\n            // si no, algún nodo no está en la componente 0: no se llega a ella desde ahí\n            if(tarjan.SCC_index[i] != 0){\n                cout << i+1 << \" \" << tarjan.SCC.front().front()+1 << \"\\n\";\n                return 0; \n            }\n        }\n    }\n}\n"}, {"id": "Graphs-Algorithms-Graph-Traversal-TopologicalSort", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Graph Traversal", "archivo": "Graphs/Algorithms/Graph Traversal/TopologicalSort.cpp", "nombre": "TopologicalSort", "algoritmo": "Orden topológico (Kahn)", "problema": "CSES 1679 - Course Schedule (https://cses.fi/problemset/task/1679)", "cses": "https://cses.fi/problemset/task/1679", "entrada": "n m, luego m aristas dirigidas \"a b\"", "salida": "un orden topológico, o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Orden topológico (Kahn)\n * Problema  : CSES 1679 - Course Schedule (https://cses.fi/problemset/task/1679)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : un orden topológico, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    ll n, m;\n    cin >> n >> m;\n\n    vector<vector<ll>> G(n);\n    // indeg[v] = aristas que entran a v\n    vector<ll> indeg(n, 0);\n    for (ll i = 0; i < m; ++i) {\n        ll u, v;\n        cin >> u >> v;\n        u--, v--;\n        G[u].push_back(v);\n        indeg[v]++;\n    }\n\n    // Kahn: se procesan primero los nodos sin aristas entrantes\n    // nodos sin dependencias pendientes\n    queue<ll> q;\n    for (ll i = 0; i < n; ++i)\n        if (indeg[i] == 0) q.push(i);\n\n    vector<ll> order;\n    while (!q.empty()) {\n        ll v = q.front(); q.pop();\n        order.push_back(v);\n        for (ll u : G[v]) {\n            // al sacar v se \"borran\" sus aristas; u queda libre al llegar a 0\n            if (--indeg[u] == 0) q.push(u);\n        }\n    }\n\n    // si no entraron todos los nodos hay un ciclo\n    if ((ll)order.size() < n) {\n        cout << \"IMPOSSIBLE\\n\";\n    } else {\n        for (ll v : order) cout << v + 1 << ' ';\n        cout << '\\n';\n    }\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-MST-Kruskal", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/MST", "archivo": "Graphs/Algorithms/MST/Kruskal.cpp", "nombre": "Kruskal", "algoritmo": "Kruskal (árbol de expansión mínima con DSU)", "problema": "CSES 1675 - Road Reparation (https://cses.fi/problemset/task/1675)", "cses": "https://cses.fi/problemset/task/1675", "entrada": "n m, luego m aristas \"a b c\" (costo c)", "salida": "el costo mínimo para conectar todo, o IMPOSSIBLE", "complejidad": "tiempo O(m log m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Kruskal (árbol de expansión mínima con DSU)\n * Problema  : CSES 1675 - Road Reparation (https://cses.fi/problemset/task/1675)\n * Entrada   : n m, luego m aristas \"a b c\" (costo c)\n * Salida    : el costo mínimo para conectar todo, o IMPOSSIBLE\n * Complejidad: tiempo O(m log m), memoria O(n + m)\n */\n\n// DSU para detectar si una arista une componentes distintas\nstruct DSU {\n    vector<int> parent, size;\n\n    DSU(int n) {\n        parent.resize(n + 1);\n        size.assign(n + 1, 1);\n        iota(all(parent), 0);\n    }\n\n    int find(int x) {\n        return parent[x] == x ? x : parent[x] = find(parent[x]);\n    }\n\n    bool unite(int a, int b) {\n        a = find(a), b = find(b);\n        if (a == b) return false;\n        if (size[a] < size[b]) swap(a, b);\n        parent[b] = a;\n        size[a] += size[b];\n        return true;\n    }\n};\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<array<ll, 3>> edges(m);  // {peso, a, b}\n    for (auto &e : edges) cin >> e[1] >> e[2] >> e[0];\n    // se procesan las aristas de menor a mayor peso\n    sort(all(edges));\n\n    DSU dsu(n);\n    ll total = 0;\n    int used = 0;\n    for (auto &[w, a, b] : edges) {\n        // la arista se usa solo si no forma ciclo\n        if (dsu.unite(a, b)) {\n            total += w;\n            used++;\n        }\n    }\n\n    // un árbol de expansión tiene n-1 aristas; si faltan, el grafo no es conexo\n    if (used != n - 1) cout << \"IMPOSSIBLE\\n\";\n    else cout << total << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-MST-Prim", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/MST", "archivo": "Graphs/Algorithms/MST/Prim.cpp", "nombre": "Prim", "algoritmo": "Prim (árbol de expansión mínima con cola de prioridad)", "problema": "CSES 1675 - Road Reparation (https://cses.fi/problemset/task/1675)", "cses": "https://cses.fi/problemset/task/1675", "entrada": "n m, luego m aristas \"a b c\" (costo c)", "salida": "el costo mínimo para conectar todo, o IMPOSSIBLE", "complejidad": "tiempo O(m log n), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Prim (árbol de expansión mínima con cola de prioridad)\n * Problema  : CSES 1675 - Road Reparation (https://cses.fi/problemset/task/1675)\n * Entrada   : n m, luego m aristas \"a b c\" (costo c)\n * Salida    : el costo mínimo para conectar todo, o IMPOSSIBLE\n * Complejidad: tiempo O(m log n), memoria O(n + m)\n */\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<vector<pair<int, ll>>> G(n + 1);\n    for (int i = 0; i < m; i++) {\n        int a, b;\n        ll c;\n        cin >> a >> b >> c;\n        G[a].push_back({b, c});\n        G[b].push_back({a, c});\n    }\n\n    vector<bool> inTree(n + 1, false);\n    // min-heap de {peso de la arista, nodo} para crecer el árbol desde el nodo 1\n    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;\n    pq.push({0, 1});\n    ll total = 0;\n    int used = 0;\n    while (!pq.empty()) {\n        auto [w, u] = pq.top();\n        pq.pop();\n        // el nodo ya está en el árbol\n        if (inTree[u]) continue;\n        inTree[u] = true;\n        // se agrega el nodo con la arista más barata que lo conecta\n        total += w;\n        used++;\n        for (auto [v, c] : G[u])\n            if (!inTree[v]) pq.push({c, v});\n    }\n\n    // si no entraron todos, el grafo no es conexo\n    if (used != n) cout << \"IMPOSSIBLE\\n\";\n    else cout << total << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Miscellaneous-2-SAT", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Miscellaneous", "archivo": "Graphs/Algorithms/Miscellaneous/2-SAT.cpp", "nombre": "2-SAT", "algoritmo": "2-SAT con componentes fuertemente conexas (Tarjan)", "problema": "CSES 1684 - Giant Pizza (https://cses.fi/problemset/task/1684)", "cses": "https://cses.fi/problemset/task/1684", "entrada": "n m, luego n líneas \"+ a - b\" (deseos de cada persona sobre m ingredientes)", "salida": "una asignación \"+/-\" por ingrediente, o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : 2-SAT con componentes fuertemente conexas (Tarjan)\n * Problema  : CSES 1684 - Giant Pizza (https://cses.fi/problemset/task/1684)\n * Entrada   : n m, luego n líneas \"+ a - b\" (deseos de cada persona sobre m ingredientes)\n * Salida    : una asignación \"+/-\" por ingrediente, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// Tarjan: componentes fuertemente conexas (SCC) con una sola DFS\nstruct Tarjan{\n    // tempo = contador de descubrimiento\n    ll tempo = 0;\n    vector<vector<ll>> ady;\n    // discovered[v] = momento en que se visitó v, low[v] = menor tiempo alcanzable desde su subárbol\n    vector<ll> discovered;\n    vector<ll> low;\n    // pila de nodos de la SCC actual; in_stack evita usar aristas hacia SCC ya cerradas\n    stack<ll> ss;\n    vector<bool> in_stack;\n    // SCC = lista de componentes, SCC_index[v] = componente de v\n    vector<vector<ll>> SCC;\n    vector<ll> SCC_index;\n \n    Tarjan(ll n){\n        ady.assign(n, vector<ll>());\n        discovered.assign(n, -1);\n        low.assign(n, -1);\n        in_stack.assign(n, false);\n        SCC_index.assign(n, -1);\n    }\n \n    void add_edge(ll u, ll v){\n        ady[u].push_back(v);\n    }\n \n    // DFS de Tarjan\n    void DFS(ll v){\n        discovered[v] = tempo;\n        low[v] = tempo;\n        tempo++;\n \n        ss.push(v);\n        in_stack[v] = true;\n \n        for(auto u: ady[v]){\n            // arista de árbol: se baja y se actualiza low con el hijo\n            if(discovered[u] == -1){\n                DFS(u);\n                low[v] = min(low[v], low[u]);\n            }\n            // arista hacia atrás dentro de la misma componente\n            else if(in_stack[u]){\n                low[v] = min(low[v], discovered[u]);\n            }\n        }\n \n        // v es la raíz de una SCC: se desapila hasta v\n        if(low[v] == discovered[v]){\n            vector<ll> newSCC;\n            ll w;\n            do {\n                w = ss.top(); ss.pop();\n                SCC_index[w] = SCC.size();\n                newSCC.push_back(w);\n                in_stack[w] = false;\n            } while (w != v);\n            SCC.push_back(newSCC);\n        }\n    }\n};\n \nint main(){\n    fastio;\n    \n    ll n, m; cin >> n >> m;\n    // 2-SAT: n cláusulas y m variables; el nodo x es \"x verdadero\" y x+m es su negación\n    Tarjan tarjan(2*m+1);\n \n    // negación de un literal\n    auto negation = [&](ll u){\n        if(u > m) return u - m;\n        else return u + m;\n    };\n \n    for(int i = 0; i < n; i++){\n        // cada cláusula (a ∨ b) agrega las implicaciones ¬a → b y ¬b → a\n        char type1, type2; ll u, v; \n        cin >> type1 >> u >> type2  >> v;\n        // se lee \"+ x\" como literal x; se guarda su negación para armar las implicaciones\n        if(type1 == '+') u = negation(u);\n        if(type2 == '+') v = negation(v);\n \n        tarjan.add_edge(negation(u), v);\n        tarjan.add_edge(negation(v), u);\n    }\n \n    // SCC sobre el grafo de implicaciones\n    for(int i = 1; i < 2*m+1; i++){\n        if(tarjan.discovered[i] == -1){\n            tarjan.DFS(i);\n        }\n    }\n \n    // si x y ¬x están en la misma SCC no hay solución\n    bool agg = true;\n    for(int i = 1; i <= m; i++){\n        if(tarjan.SCC_index[i] == tarjan.SCC_index[negation(i)]){\n            agg = false;\n            break;\n        }\n    }\n \n    if(!agg){\n        cout << \"IMPOSSIBLE\" << \"\\n\";\n    }\n    else{\n        // x es verdadera si su SCC sale después que la de ¬x en el orden topológico (Tarjan numera al revés)\n        string res = \"\";\n        for(int i = 1; i <= m; i++){\n            if(tarjan.SCC_index[i] < tarjan.SCC_index[negation(i)]) res += '-';\n            else res += '+';\n        }\n \n        for(auto c: res) cout << c << \" \";\n        cout << \"\\n\";\n    }\n}\n"}, {"id": "Graphs-Algorithms-Miscellaneous-CycleFindingDirected", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Miscellaneous", "archivo": "Graphs/Algorithms/Miscellaneous/CycleFindingDirected.cpp", "nombre": "CycleFindingDirected", "algoritmo": "Ciclo en grafo dirigido (DFS con pila de recursión)", "problema": "CSES 1678 - Round Trip II (https://cses.fi/problemset/task/1678)", "cses": "https://cses.fi/problemset/task/1678", "entrada": "n m, luego m aristas dirigidas \"a b\"", "salida": "longitud del ciclo y sus nodos, o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Ciclo en grafo dirigido (DFS con pila de recursión)\n * Problema  : CSES 1678 - Round Trip II (https://cses.fi/problemset/task/1678)\n * Entrada   : n m, luego m aristas dirigidas \"a b\"\n * Salida    : longitud del ciclo y sus nodos, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// on_stack = nodos en el camino actual de la DFS, parent[] sirve para reconstruir el ciclo\nvector<bool> on_stack;\nvector<bool> vis;\nvector<vector<ll>> ady;\nvector<ll> cycle;\nvector<ll> parent;\n \n// devuelve true apenas encuentra un ciclo\nbool DFS(ll v){\n    vis[v] = true;\n    on_stack[v] = true;\n \n    for (auto u : ady[v]) {\n        if (!vis[u]) {\n            parent[u] = v;\n            if (DFS(u)) return true;\n        // arista hacia un nodo del camino actual: ciclo dirigido\n        } else if (on_stack[u]) {\n            cycle.clear();\n            cycle.push_back(u);\n            // se retrocede por los padres desde v hasta u\n            for (ll x = v; x != u; x = parent[x]) {\n                cycle.push_back(x);\n            }\n            cycle.push_back(u);\n            // se invierte para imprimirlo en el sentido de las aristas\n            reverse(all(cycle));\n            return true;\n        }\n    }\n \n    // v ya no está en el camino actual\n    on_stack[v] = false;\n    return false;\n}\n \nint main(){\n    fastio;\n \n    ll n, m; cin >> n >> m;\n    ady.assign(n, {});\n    for (int i = 0; i < m; i++){\n        ll u, v; cin >> u >> v; u--; v--;\n        ady[u].push_back(v);\n    }\n \n    on_stack.assign(n, false);\n    vis.assign(n, false);\n    parent.assign(n, -1);\n \n    for (int i = 0; i < n; i++){\n        if (!vis[i]) {\n            // se prueba cada componente\n            if (DFS(i)) {\n                cout << cycle.size() << \"\\n\";\n                for (auto node : cycle) cout << node + 1 << \" \";\n                cout << \"\\n\";\n                return 0;\n            }\n        }\n    }\n \n    cout << \"IMPOSSIBLE\\n\";\n}\n"}, {"id": "Graphs-Algorithms-Miscellaneous-CycleFindingUndirected", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Miscellaneous", "archivo": "Graphs/Algorithms/Miscellaneous/CycleFindingUndirected.cpp", "nombre": "CycleFindingUndirected", "algoritmo": "Ciclo en grafo no dirigido (DFS)", "problema": "CSES 1669 - Round Trip (https://cses.fi/problemset/task/1669)", "cses": "https://cses.fi/problemset/task/1669", "entrada": "n m, luego m aristas \"a b\"", "salida": "longitud del ciclo y sus nodos, o IMPOSSIBLE", "complejidad": "tiempo O(n + m), memoria O(n + m)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Ciclo en grafo no dirigido (DFS)\n * Problema  : CSES 1669 - Round Trip (https://cses.fi/problemset/task/1669)\n * Entrada   : n m, luego m aristas \"a b\"\n * Salida    : longitud del ciclo y sus nodos, o IMPOSSIBLE\n * Complejidad: tiempo O(n + m), memoria O(n + m)\n */\n\n// on_stack = nodos en el camino actual de la DFS, parent[] sirve para reconstruir el ciclo\nvector<bool> on_stack;\nvector<bool> vis;\nvector<vector<ll>> ady;\nvector<ll> cycle;\nvector<ll> parent;\n \n// devuelve true apenas encuentra un ciclo\nbool DFS(ll v, ll p){\n    parent[v] = p;\n    vis[v] = true;\n    on_stack[v] = true;\n \n    for (auto u : ady[v]) {\n        // no se cuenta la arista por la que se llegó (padre)\n        if(u == p) continue;\n \n        if (!vis[u]) {\n            if (DFS(u, v)) return true;\n        // se llegó a un ancestro: hay un ciclo\n        } else if (on_stack[u]) {\n            cycle.clear();\n            cycle.push_back(u);\n            // se retrocede por los padres desde v hasta u\n            for (ll x = v; x != u; x = parent[x]) {\n                cycle.push_back(x);\n            }\n            cycle.push_back(u); \n            return true;\n        }\n    }\n \n    // v ya no está en el camino actual\n    on_stack[v] = false;\n    return false;\n}\n \nint main(){\n    fastio;\n \n    ll n, m; cin >> n >> m;\n    ady.assign(n, {});\n    for (int i = 0; i < m; i++){\n        ll u, v; cin >> u >> v; u--; v--;\n        ady[u].push_back(v);\n        ady[v].push_back(u);\n    }\n \n    on_stack.assign(n, false);\n    vis.assign(n, false);\n    parent.assign(n, -1);\n \n    for (int i = 0; i < n; i++){\n        if (!vis[i]) {\n            // se prueba cada componente conexa\n            if (DFS(i, -1)) {\n                cout << cycle.size() << \"\\n\";\n                for (auto node : cycle) cout << node + 1 << \" \";\n                cout << \"\\n\";\n                return 0;\n            }\n        }\n    }\n \n    cout << \"IMPOSSIBLE\\n\";\n}\n"}, {"id": "Graphs-Algorithms-Trees-BinaryLifting", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/BinaryLifting.cpp", "nombre": "BinaryLifting", "algoritmo": "Binary Lifting (ancestro a distancia k)", "problema": "CSES 1750 - Planets Queries I (https://cses.fi/problemset/task/1750)", "cses": "https://cses.fi/problemset/task/1750", "entrada": "n q, luego t_1..t_n (destino de cada planeta) y q consultas \"x k\"", "salida": "el planeta al que se llega desde x tras k teletransportes", "complejidad": "tiempo O((n + q) log k), memoria O(n log k)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Binary Lifting (ancestro a distancia k)\n * Problema  : CSES 1750 - Planets Queries I (https://cses.fi/problemset/task/1750)\n * Entrada   : n q, luego t_1..t_n (destino de cada planeta) y q consultas \"x k\"\n * Salida    : el planeta al que se llega desde x tras k teletransportes\n * Complejidad: tiempo O((n + q) log k), memoria O(n log k)\n */\n\n// 2^30 > 10^9, suficiente para k hasta 10^9\nconst int LOG = 30;\n\nint main() {\n    fastio;\n    int n, q;\n    cin >> n >> q;\n    // up[j][v] = nodo al que se llega desde v tras 2^j pasos\n    // up[j][v] = nodo al que se llega desde v tras 2^j pasos\n    vector<vector<int>> up(LOG, vector<int>(n + 1));\n    for (int v = 1; v <= n; v++) cin >> up[0][v];\n    // cada nivel sale de duplicar el anterior\n    for (int j = 1; j < LOG; j++)\n        for (int v = 1; v <= n; v++)\n            up[j][v] = up[j - 1][up[j - 1][v]];\n\n    while (q--) {\n        int x, k;\n        cin >> x >> k;\n        for (int j = 0; j < LOG; j++)\n            // se descompone k en binario y se salta por cada bit encendido\n            if (k >> j & 1) x = up[j][x];\n        cout << x << \"\\n\";\n    }\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Trees-Centroid", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/Centroid.cpp", "nombre": "Centroid", "algoritmo": "Centroide de un árbol (tamaños de subárbol)", "problema": "CSES 2079 - Finding a Centroid (https://cses.fi/problemset/task/2079)", "cses": "https://cses.fi/problemset/task/2079", "entrada": "n, luego n-1 aristas \"a b\"", "salida": "un centroide", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Centroide de un árbol (tamaños de subárbol)\n * Problema  : CSES 2079 - Finding a Centroid (https://cses.fi/problemset/task/2079)\n * Entrada   : n, luego n-1 aristas \"a b\"\n * Salida    : un centroide\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nint main() {\n    fastio;\n\n    int n;\n    cin >> n;\n    vector<vector<int>> adj(n+1);\n    for (int i = 0; i < n-1; i++) {\n        int a, b;\n        cin >> a >> b;\n        adj[a].push_back(b);\n        adj[b].push_back(a);\n    }\n\n    // DFS iterativo: order guarda los nodos en preorden y parent su padre\n    vector<int> parent(n+1, 0), order;\n    order.reserve(n);\n    stack<pair<int, int>> st;\n    st.emplace(1, 0);\n\n    while (!st.empty()) {\n        auto [u, p] = st.top(); st.pop();\n        parent[u] = p;\n        order.push_back(u);\n        for (int v : adj[u]) {\n            if (v == p) continue;\n            st.emplace(v, u);\n        }\n    }\n\n    // dp[u] = tamaño del subárbol de u (se llena de las hojas hacia la raíz)\n    vector<int> dp(n+1, 1);\n    for (int i = n-1; i >= 0; --i) {\n        int u = order[i];\n        for (int v : adj[u]) {\n            if (v == parent[u]) continue;\n            dp[u] += dp[v];\n        }\n    }\n\n    // centroide: ningún subárbol puede tener más de n/2 nodos\n    int limit = n / 2;\n    int u = 1;\n    // se baja siempre hacia el hijo con subárbol demasiado grande\n    while (true) {\n        bool moved = false;\n        for (int v : adj[u]) {\n            if (v != parent[u] && dp[v] > limit) {\n                parent[u] = u;\n                u = v;\n                moved = true;\n                break;\n            }\n        }\n        if (moved) continue;\n\n        // si tampoco la parte \"de arriba\" es grande, u es el centroide\n        if (n - dp[u] <= limit) {\n            cout << u << '\\n';\n            break;\n        }\n\n        u = parent[u];\n    }\n\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Trees-CentroidDecomposition", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/CentroidDecomposition.cpp", "nombre": "CentroidDecomposition", "algoritmo": "Descomposición por centroides (caminos de longitud fija)", "problema": "CSES 2080 - Fixed-Length Paths I (https://cses.fi/problemset/task/2080)", "cses": "https://cses.fi/problemset/task/2080", "entrada": "n k, luego n-1 aristas \"a b\"", "salida": "cantidad de caminos con exactamente k aristas", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Descomposición por centroides (caminos de longitud fija)\n * Problema  : CSES 2080 - Fixed-Length Paths I (https://cses.fi/problemset/task/2080)\n * Entrada   : n k, luego n-1 aristas \"a b\"\n * Salida    : cantidad de caminos con exactamente k aristas\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint n, k;\nvector<vector<int>> G;\nvector<int> sz, cnt;\nvector<bool> removed;\nll answer = 0;\nint maxDepth;\n\n// tamaño de cada subárbol (ignorando centroides ya removidos)\nint calcSize(int u, int p) {\n    sz[u] = 1;\n    for (int v : G[u])\n        if (v != p && !removed[v]) sz[u] += calcSize(v, u);\n    return sz[u];\n}\n\n// baja hacia el hijo con más de la mitad de los nodos\nint findCentroid(int u, int p, int total) {\n    for (int v : G[u])\n        if (v != p && !removed[v] && sz[v] * 2 > total) return findCentroid(v, u, total);\n    return u;\n}\n\n// cuenta caminos que pasan por el centroide usando cnt[d] = nodos a profundidad d ya vistos\n// recorre un subárbol: con fill se registra la profundidad, sin fill se cuentan caminos de longitud k\nvoid collect(int u, int p, int depth, bool fill) {\n    if (depth > k) return;\n    if (fill) cnt[depth]++;\n    else answer += cnt[k - depth];\n    maxDepth = max(maxDepth, depth);\n    for (int v : G[u])\n        if (v != p && !removed[v]) collect(v, u, depth + 1, fill);\n}\n\n// 1) se halla el centroide, 2) se cuentan los caminos que pasan por él, 3) se repite en cada parte\nvoid decompose(int root) {\n    int total = calcSize(root, 0);\n    int c = findCentroid(root, 0, total);\n    removed[c] = true;\n\n    cnt[0] = 1;\n    int used = 0;\n    for (int v : G[c]) {\n        if (removed[v]) continue;\n        maxDepth = 0;\n        // primero se consulta contra los subárboles anteriores\n        collect(v, c, 1, false);  // primero se consulta contra los subárboles anteriores\n        collect(v, c, 1, true);   // luego se agrega este subárbol\n        used = max(used, maxDepth);\n    }\n    // se limpia cnt para el siguiente centroide\n    for (int d = 0; d <= min(used, k); d++) cnt[d] = 0;\n\n    for (int v : G[c])\n        if (!removed[v]) decompose(v);\n}\n\nint main() {\n    fastio;\n    cin >> n >> k;\n    G.assign(n + 1, {});\n    sz.assign(n + 1, 0);\n    cnt.assign(n + 2, 0);\n    removed.assign(n + 1, false);\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        G[b].push_back(a);\n    }\n    decompose(1);\n    cout << answer << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Trees-EulerTour", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/EulerTour.cpp", "nombre": "EulerTour", "algoritmo": "Euler Tour + Fenwick Tree (consultas sobre subárboles)", "problema": "CSES 1137 - Subtree Queries (https://cses.fi/problemset/task/1137)", "cses": "https://cses.fi/problemset/task/1137", "entrada": "n q, n valores, n-1 aristas y q consultas: \"1 s x\" (valor del nodo s = x) o \"2 s\" (suma del subárbol de s)", "salida": "la suma de cada consulta de tipo 2", "complejidad": "tiempo O((n + q) log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Euler Tour + Fenwick Tree (consultas sobre subárboles)\n * Problema  : CSES 1137 - Subtree Queries (https://cses.fi/problemset/task/1137)\n * Entrada   : n q, n valores, n-1 aristas y q consultas: \"1 s x\" (valor del nodo s = x) o \"2 s\" (suma del subárbol de s)\n * Salida    : la suma de cada consulta de tipo 2\n * Complejidad: tiempo O((n + q) log n), memoria O(n)\n */\n\nint n;\nvector<vector<int>> G;\n// tin[u]/tout[u] = intervalo del subárbol de u en el recorrido\nvector<int> tin, tout;\n// Fenwick Tree sobre las posiciones del recorrido\nvector<ll> bit;\n\n// suma v en la posición i\nvoid add(int i, ll v) {\n    for (; i <= n; i += i & -i) bit[i] += v;\n}\n\n// suma del prefijo [1..i]\nll sum(int i) {\n    ll s = 0;\n    for (; i > 0; i -= i & -i) s += bit[i];\n    return s;\n}\n\nint main() {\n    fastio;\n    int q;\n    cin >> n >> q;\n    vector<ll> val(n + 1);\n    for (int i = 1; i <= n; i++) cin >> val[i];\n    G.assign(n + 1, {});\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        G[b].push_back(a);\n    }\n\n    // DFS iterativo: tin/tout marcan el intervalo del subárbol\n    tin.assign(n + 1, 0), tout.assign(n + 1, 0);\n    vector<int> parent(n + 1, 0), idx(n + 1, 0), st = {1};\n    int timer = 0;\n    tin[1] = ++timer;\n    while (!st.empty()) {\n        int u = st.back();\n        if (idx[u] < (int)G[u].size()) {\n            int v = G[u][idx[u]++];\n            if (v == parent[u]) continue;\n            parent[v] = u;\n            tin[v] = ++timer;\n            st.push_back(v);\n        }\n        else {\n            tout[u] = timer;\n            st.pop_back();\n        }\n    }\n\n    bit.assign(n + 2, 0);\n    // cada nodo ocupa la posición tin[i]\n    for (int i = 1; i <= n; i++) add(tin[i], val[i]);\n\n    while (q--) {\n        int type, s;\n        cin >> type >> s;\n        // actualizar un nodo = sumar la diferencia en su posición; consultar = suma del intervalo del subárbol\n        if (type == 1) {\n            ll x;\n            cin >> x;\n            add(tin[s], x - val[s]);\n            val[s] = x;\n        }\n        else cout << sum(tout[s]) - sum(tin[s] - 1) << \"\\n\";\n    }\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Trees-LCA", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/LCA.cpp", "nombre": "LCA", "algoritmo": "LCA con binary lifting", "problema": "CSES 1688 - Company Queries II (https://cses.fi/problemset/task/1688)", "cses": "https://cses.fi/problemset/task/1688", "entrada": "n q, luego los jefes de 2..n y q consultas \"a b\"", "salida": "el ancestro común más bajo de cada consulta", "complejidad": "tiempo O((n + q) log n), memoria O(n log n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : LCA con binary lifting\n * Problema  : CSES 1688 - Company Queries II (https://cses.fi/problemset/task/1688)\n * Entrada   : n q, luego los jefes de 2..n y q consultas \"a b\"\n * Salida    : el ancestro común más bajo de cada consulta\n * Complejidad: tiempo O((n + q) log n), memoria O(n log n)\n */\n\nint main() {\n    fastio;\n\n    ll n, q;\n    cin >> n >> q;\n\n    vector<vector<ll>> children(n + 1);\n    // read bosses e[2..n]\n    for (ll i = 2; i <= n; ++i) {\n        ll b;\n        cin >> b;\n        children[b].push_back(i);\n    }\n\n    // compute depth and immediate parent\n    vector<ll> depth(n + 1), parent(n + 1);\n    queue<ll> bfs;\n    depth[1] = 0;\n    parent[1] = 1;\n    bfs.push(1);\n    while (!bfs.empty()) {\n        ll u = bfs.front(); bfs.pop();\n        for (ll v : children[u]) {\n            depth[v] = depth[u] + 1;\n            parent[v] = u;\n            bfs.push(v);\n        }\n    }\n\n    // binary lifting table\n    // up[i][j] = ancestro 2^j veces arriba de i\n    const int LOG = 19; // since 2^18 > 2e5\n    vector<array<ll, LOG>> up(n + 1);\n    for (ll i = 1; i <= n; ++i) {\n        up[i][0] = parent[i];\n    }\n    for (int j = 1; j < LOG; ++j) {\n        for (ll i = 1; i <= n; ++i) {\n            up[i][j] = up[ up[i][j - 1] ][j - 1];\n        }\n    }\n\n    // LCA: se igualan profundidades y luego se sube a la vez mientras los ancestros difieran\n    auto lca = [&](ll a, ll b) {\n        if (depth[a] < depth[b]) swap(a, b);\n        ll diff = depth[a] - depth[b];\n        for (int j = 0; j < LOG; ++j) {\n            if (diff & (1LL << j)) {\n                a = up[a][j];\n            }\n        }\n        if (a == b) return a;\n        for (int j = LOG - 1; j >= 0; --j) {\n            if (up[a][j] != up[b][j]) {\n                a = up[a][j];\n                b = up[b][j];\n            }\n        }\n        return parent[a];\n    };\n\n    while (q--) {\n        ll a, b;\n        cin >> a >> b;\n        cout << lca(a, b) << '\\n';\n    }\n\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Trees-TreeDistances", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/TreeDistances.cpp", "nombre": "TreeDistances", "algoritmo": "Distancia máxima desde cada nodo (extremos del diámetro)", "problema": "CSES 1132 - Tree Distances I (https://cses.fi/problemset/task/1132)", "cses": "https://cses.fi/problemset/task/1132", "entrada": "n, luego n-1 aristas \"a b\"", "salida": "para cada nodo, la distancia al nodo más lejano", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Distancia máxima desde cada nodo (extremos del diámetro)\n * Problema  : CSES 1132 - Tree Distances I (https://cses.fi/problemset/task/1132)\n * Entrada   : n, luego n-1 aristas \"a b\"\n * Salida    : para cada nodo, la distancia al nodo más lejano\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\nvector<vector<int>> G;\n\n// BFS: distancias desde s\n// BFS: distancias desde s\nvector<int> bfs(int s) {\n    vector<int> dist(G.size(), -1);\n    queue<int> q;\n    dist[s] = 0;\n    q.push(s);\n    while (!q.empty()) {\n        int u = q.front();\n        q.pop();\n        for (int v : G[u])\n            if (dist[v] == -1) {\n                dist[v] = dist[u] + 1;\n                q.push(v);\n            }\n    }\n    return dist;\n}\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    G.assign(n + 1, {});\n    for (int i = 0; i < n - 1; i++) {\n        int a, b;\n        cin >> a >> b;\n        G[a].push_back(b);\n        G[b].push_back(a);\n    }\n\n    // el más lejano de cualquier nodo es un extremo A del diámetro; el más lejano de A es B\n    // el nodo más lejano de cualquier nodo es un extremo A del diámetro\n    auto d0 = bfs(1);\n    int A = max_element(d0.begin() + 1, d0.end()) - d0.begin();\n    auto dA = bfs(A);\n    int B = max_element(dA.begin() + 1, dA.end()) - dA.begin();\n    auto dB = bfs(B);\n\n    // la distancia máxima desde v es max(dist a A, dist a B)\n    // la distancia máxima desde v es max(dist a A, dist a B)\n    for (int v = 1; v <= n; v++) cout << max(dA[v], dB[v]) << ' ';\n    cout << \"\\n\";\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Trees-TreeIsomorfism", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/TreeIsomorfism.cpp", "nombre": "TreeIsomorfism", "algoritmo": "Isomorfismo de árboles sin raíz (centroides + IDs canónicos)", "problema": "CSES 1701 - Tree Isomorphism II (https://cses.fi/problemset/task/1701)", "cses": "https://cses.fi/problemset/task/1701", "entrada": "t casos; cada uno: n, aristas del primer árbol y aristas del segundo", "salida": "YES o NO por caso", "complejidad": "tiempo O(n log n) por caso, memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Isomorfismo de árboles sin raíz (centroides + IDs canónicos)\n * Problema  : CSES 1701 - Tree Isomorphism II (https://cses.fi/problemset/task/1701)\n * Entrada   : t casos; cada uno: n, aristas del primer árbol y aristas del segundo\n * Salida    : YES o NO por caso\n * Complejidad: tiempo O(n log n) por caso, memoria O(n)\n */\n\nconst int MAXN = 100000 + 1;\n\nint n, cidCounter;\n// adj[t][u] = lista de vecinos del nodo u en el árbol t (t=0,1)\nvector<int> adj[2][MAXN];\n// sizeSub[t][u] = tamaño del subárbol en u en el árbol t\nint sizeSub[2][MAXN];\n// canonId[t][u] = identificador canónico del subárbol en u\nint canonId[2][MAXN];\n// posibles centroides de cada árbol\nvector<int> centers[2];\n// mapa de vectores de hijos ordenados → nuevo ID\nmap<vector<int>, int> idmap;\n\n// Restaurar estructuras entre casos\nvoid reset() {\n    idmap.clear();\n    cidCounter = 0;\n    for (int t = 0; t < 2; t++) {\n        centers[t].clear();\n        for (int i = 1; i <= n; i++) {\n            adj[t][i].clear();\n            sizeSub[t][i] = canonId[t][i] = 0;\n        }\n    }\n}\n\n// DFS para hallar centroides: marca u si ningún subárbol > n/2\nvoid dfs_centroid(int t, int u, int p) {\n    sizeSub[t][u] = 1;\n    bool ok = true;\n    for (int v : adj[t][u]) if (v != p) {\n        dfs_centroid(t, v, u);\n        sizeSub[t][u] += sizeSub[t][v];\n        if (sizeSub[t][v] > n/2) ok = false;\n    }\n    if (n - sizeSub[t][u] > n/2) ok = false;\n    if (ok) centers[t].push_back(u);\n}\n\n// DFS para asignar IDs canónicos basados en multiconjuntos de hijos\nvoid dfs_canonical(int t, int u, int p) {\n    vector<int> childIds;\n    for (int v : adj[t][u]) if (v != p) {\n        dfs_canonical(t, v, u);\n        childIds.push_back(canonId[t][v]);\n    }\n    sort(all(childIds));                   // ordenamos para multiconjunto\n    if (!idmap[childIds])                  // si no existe el patrón\n        idmap[childIds] = ++cidCounter;    // creamos uno nuevo\n    canonId[t][u] = idmap[childIds];       // asignamos al nodo\n}\n\n// Resolver un caso: leer, hallar centroides y comparar isomorfismos\nvoid solve_case() {\n    cin >> n;\n    reset();\n    for (int t = 0; t < 2; t++) {\n        for (int i = 0, u, v; i < n-1; i++) {\n            cin >> u >> v;\n            adj[t][u].push_back(v);\n            adj[t][v].push_back(u);\n        }\n        dfs_centroid(t, 1, -1);\n    }\n    // probamos cada par de centroides\n    for (int c0 : centers[0]) {\n        for (int c1 : centers[1]) {\n            idmap.clear();\n            dfs_canonical(0, c0, -1);\n            dfs_canonical(1, c1, -1);\n            if (canonId[0][c0] == canonId[1][c1]) {\n                cout << \"YES\\n\";\n                return;\n            }\n        }\n    }\n    cout << \"NO\\n\";\n}\n\nint main() {\n    fastio;\n    int T;\n    cin >> T;\n    while (T--) solve_case();\n    return 0;\n}\n"}, {"id": "Graphs-Algorithms-Trees-TreeIsomorfismRooted", "carpeta": "Graphs", "area": "Grafos", "sub": "Algorithms/Trees", "archivo": "Graphs/Algorithms/Trees/TreeIsomorfismRooted.cpp", "nombre": "TreeIsomorfismRooted", "algoritmo": "Isomorfismo de árboles con raíz (ids canónicos compartidos)", "problema": "CSES 1700 - Tree Isomorphism I (https://cses.fi/problemset/task/1700)", "cses": "https://cses.fi/problemset/task/1700", "entrada": "t casos: n, luego n-1 aristas del primer árbol y n-1 del segundo (ambos con raíz 1)", "salida": "YES si los árboles con raíz son isomorfos, NO si no", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Isomorfismo de árboles con raíz (ids canónicos compartidos)\n * Problema  : CSES 1700 - Tree Isomorphism I (https://cses.fi/problemset/task/1700)\n * Entrada   : t casos: n, luego n-1 aristas del primer árbol y n-1 del segundo (ambos con raíz 1)\n * Salida    : YES si los árboles con raíz son isomorfos, NO si no\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\n// cada lista ordenada de ids de hijos recibe un id único\nmap<vector<int>, int> ids;  // compartido entre los dos árboles de cada caso\n\n// id canónico de cada nodo: depende de los ids ordenados de sus hijos\n// calcula el id canónico de la raíz del árbol\nint canonical(const vector<vector<int>> &G) {\n    int n = G.size() - 1;\n    // BFS para obtener un orden y el padre de cada nodo\n    vector<int> parent(n + 1, 0), order;\n    order.push_back(1);\n    for (int i = 0; i < (int)order.size(); i++) {\n        int u = order[i];\n        for (int v : G[u])\n            if (v != parent[u]) {\n                parent[v] = u;\n                order.push_back(v);\n            }\n    }\n\n    vector<int> id(n + 1);\n    vector<vector<int>> children(n + 1);\n    // se procesa de las hojas hacia la raíz\n    for (int i = n - 1; i >= 0; i--) {  // de las hojas hacia la raíz\n        int u = order[i];\n        sort(all(children[u]));\n        auto it = ids.find(children[u]);\n        if (it == ids.end()) it = ids.insert({children[u], (int)ids.size()}).first;\n        id[u] = it->second;\n        if (parent[u]) children[parent[u]].push_back(id[u]);\n    }\n    return id[1];\n}\n\nint main() {\n    fastio;\n    int t;\n    cin >> t;\n    while (t--) {\n        int n;\n        cin >> n;\n        vector<vector<int>> A(n + 1), B(n + 1);\n        for (int i = 0; i < n - 1; i++) {\n            int a, b;\n            cin >> a >> b;\n            A[a].push_back(b);\n            A[b].push_back(a);\n        }\n        for (int i = 0; i < n - 1; i++) {\n            int a, b;\n            cin >> a >> b;\n            B[a].push_back(b);\n            B[b].push_back(a);\n        }\n        // árboles con raíz isomorfos si las raíces tienen el mismo id\n        cout << (canonical(A) == canonical(B) ? \"YES\" : \"NO\") << \"\\n\";\n    }\n    return 0;\n}\n"}, {"id": "Strings-Algorithms-KMP-I", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/KMP-I.cpp", "nombre": "KMP-I", "algoritmo": "KMP con prefix-function sobre patrón + '#' + texto", "problema": "CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)", "cses": "https://cses.fi/problemset/task/1753", "entrada": "texto s y luego patrón t", "salida": "cantidad de apariciones de t en s", "complejidad": "tiempo O(|s| + |t|), memoria O(|s| + |t|)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : KMP con prefix-function sobre patrón + '#' + texto\n * Problema  : CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)\n * Entrada   : texto s y luego patrón t\n * Salida    : cantidad de apariciones de t en s\n * Complejidad: tiempo O(|s| + |t|), memoria O(|s| + |t|)\n */\n\n// LP[i] = longitud del mayor prefijo que también es sufijo de s[0..i]\nvector<int> KMP(const string &s) {\n    vector<int> LP(s.size(), 0);\n    for (int i = 1; i < (int)s.size(); i++) {\n        int j = LP[i - 1];\n        while (j > 0 && s[i] != s[j]) j = LP[j - 1];\n        if (s[i] == s[j]) j++;\n        LP[i] = j;\n    }\n    return LP;\n}\n\n// posiciones (base 0) de t dentro de s\n// se concatena t + \"#\" + s: un valor |t| en LP marca una aparición\nvector<int> PatternSearch(const string &s, const string &t) {\n    vector<int> pos;\n    string combined = t + '#' + s;\n    vector<int> lps = KMP(combined);\n    for (int i = t.size() + 1; i < (int)lps.size(); i++)\n        if (lps[i] == (int)t.size())\n            pos.push_back(i - 2 * t.size());\n    return pos;\n}\n\nint main() {\n    fastio;\n    string s, t;\n    cin >> s >> t;\n    cout << PatternSearch(s, t).size() << \"\\n\";\n    return 0;\n}\n"}, {"id": "Strings-Algorithms-KMP-II", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/KMP-II.cpp", "nombre": "KMP-II", "algoritmo": "KMP con prefix-function solo del patrón", "problema": "CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)", "cses": "https://cses.fi/problemset/task/1753", "entrada": "texto s y luego patrón t", "salida": "cantidad de apariciones de t en s", "complejidad": "tiempo O(|s| + |t|), memoria O(|t|)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : KMP con prefix-function solo del patrón\n * Problema  : CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)\n * Entrada   : texto s y luego patrón t\n * Salida    : cantidad de apariciones de t en s\n * Complejidad: tiempo O(|s| + |t|), memoria O(|t|)\n */\n\n// LP[i] = longitud del mayor prefijo que también es sufijo de s[0..i]\nvector<int> KMP(const string &s) {\n    vector<int> LP(s.size(), 0);\n    for (int i = 1; i < (int)s.size(); i++) {\n        int j = LP[i - 1];\n        while (j > 0 && s[i] != s[j]) j = LP[j - 1];\n        if (s[i] == s[j]) j++;\n        LP[i] = j;\n    }\n    return LP;\n}\n\n// posiciones (base 0) de pattern dentro de text\n// recorre el texto reutilizando LP del patrón para no retroceder\nvector<int> PatternSearch(const string &text, const string &pattern) {\n    vector<int> lp = KMP(pattern);\n    vector<int> result;\n    int j = 0;\n    for (int i = 0; i < (int)text.size(); i++) {\n        while (j > 0 && text[i] != pattern[j]) j = lp[j - 1];\n        if (text[i] == pattern[j]) j++;\n        // coincidencia completa; se sigue con el borde más largo\n        if (j == (int)pattern.size()) {\n            result.push_back(i - pattern.size() + 1);\n            j = lp[j - 1];\n        }\n    }\n    return result;\n}\n\nint main() {\n    fastio;\n    string s, t;\n    cin >> s >> t;\n    cout << PatternSearch(s, t).size() << \"\\n\";\n    return 0;\n}\n"}, {"id": "Strings-Algorithms-Manacher", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/Manacher.cpp", "nombre": "Manacher", "algoritmo": "Manacher (subcadena palíndroma más larga)", "problema": "CSES 1111 - Longest Palindrome (https://cses.fi/problemset/task/1111)", "cses": "https://cses.fi/problemset/task/1111", "entrada": "una cadena s", "salida": "la subcadena palíndroma más larga", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Manacher (subcadena palíndroma más larga)\n * Problema  : CSES 1111 - Longest Palindrome (https://cses.fi/problemset/task/1111)\n * Entrada   : una cadena s\n * Salida    : la subcadena palíndroma más larga\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\n// d1[i] = radio de palíndromos impares centrados en i, d2[i] = radio de los pares\nstring longestPalindrome(const string &s) {\n    int n = s.size();\n    // d1 = radios de palíndromos impares, d2 = radios de los pares (centro entre dos letras)\n    vector<int> d1(n), d2(n);\n    for (int i = 0, l = 0, r = -1; i < n; i++) {\n        // se reutiliza el palíndromo simétrico dentro de [l, r]\n        int k = (i > r) ? 1 : min(d1[l + r - i], r - i + 1);\n        while (i - k >= 0 && i + k < n && s[i - k] == s[i + k]) k++;\n        d1[i] = k--;\n        if (i + k > r) l = i - k, r = i + k;\n    }\n    for (int i = 0, l = 0, r = -1; i < n; i++) {\n        int k = (i > r) ? 0 : min(d2[l + r - i + 1], r - i + 1);\n        while (i - k - 1 >= 0 && i + k < n && s[i - k - 1] == s[i + k]) k++;\n        d2[i] = k--;\n        if (i + k > r) l = i - k - 1, r = i + k;\n    }\n\n    // se elige el más largo entre impares y pares\n    int best = 0, start = 0;\n    for (int i = 0; i < n; i++) {\n        if (2 * d1[i] - 1 > best) best = 2 * d1[i] - 1, start = i - d1[i] + 1;\n        if (2 * d2[i] > best) best = 2 * d2[i], start = i - d2[i];\n    }\n    return s.substr(start, best);\n}\n\nint main() {\n    fastio;\n    string s;\n    cin >> s;\n    cout << longestPalindrome(s) << \"\\n\";\n    return 0;\n}\n"}, {"id": "Strings-Algorithms-MinimalRotation", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/MinimalRotation.cpp", "nombre": "MinimalRotation", "algoritmo": "Rotación lexicográficamente mínima (algoritmo de Booth/Duval)", "problema": "CSES 1110 - Minimal Rotation (https://cses.fi/problemset/task/1110)", "cses": "https://cses.fi/problemset/task/1110", "entrada": "una cadena s", "salida": "la rotación lexicográficamente mínima de s", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Rotación lexicográficamente mínima (algoritmo de Booth/Duval)\n * Problema  : CSES 1110 - Minimal Rotation (https://cses.fi/problemset/task/1110)\n * Entrada   : una cadena s\n * Salida    : la rotación lexicográficamente mínima de s\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\n// índice de inicio de la rotación mínima\nint minimalRotation(const string &s) {\n    // la rotación mínima es una subcadena de s + s\n    string t = s + s;\n    int n = s.size(), i = 0, j = 1, k = 0;\n    // se comparan dos candidatos i y j; el peor se descarta saltando k + 1 posiciones\n    while (i < n && j < n && k < n) {\n        char a = t[i + k], b = t[j + k];\n        if (a == b) { k++; continue; }\n        if (a > b) i += k + 1;\n        else j += k + 1;\n        if (i == j) j++;\n        k = 0;\n    }\n    // el candidato que sobrevive\n    return min(i, j);\n}\n\nint main() {\n    fastio;\n    string s;\n    cin >> s;\n    int p = minimalRotation(s);\n    cout << s.substr(p) + s.substr(0, p) << \"\\n\";\n    return 0;\n}\n"}, {"id": "Strings-Algorithms-PrefixTrie", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/PrefixTrie.cpp", "nombre": "PrefixTrie", "algoritmo": "Trie (prefix tree) + DP de conteo de formas", "problema": "CSES 1731 - Word Combinations (https://cses.fi/problemset/task/1731)", "cses": "https://cses.fi/problemset/task/1731", "entrada": "cadena s, k, luego k palabras", "salida": "cantidad de formas de construir s con las palabras, módulo 10^9+7", "complejidad": "tiempo O(|s|^2 + suma de longitudes), memoria O(suma de longitudes)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Trie (prefix tree) + DP de conteo de formas\n * Problema  : CSES 1731 - Word Combinations (https://cses.fi/problemset/task/1731)\n * Entrada   : cadena s, k, luego k palabras\n * Salida    : cantidad de formas de construir s con las palabras, módulo 10^9+7\n * Complejidad: tiempo O(|s|^2 + suma de longitudes), memoria O(suma de longitudes)\n */\n\nconst int MODW = 1000000007;  // este problema pide módulo 10^9+7\n\n// cada nodo tiene un hijo por letra y marca si termina una palabra\nstruct Node {\n    int children[26];\n    bool flag = false;\n\n    Node() {\n        fill(begin(children), end(children), -1);\n    }\n};\n\n// árbol de prefijos\nstruct Trie {\n    vector<Node> Tree;\n    Trie() {\n        Tree.emplace_back();\n    }\n\n    // inserta una palabra letra por letra\n    void insert(const string &word) {\n        int v = 0;\n        for (char ch : word) {\n            int code = ch - 'a';\n            if (Tree[v].children[code] == -1) {\n                Tree[v].children[code] = Tree.size();\n                Tree.emplace_back();\n            }\n            v = Tree[v].children[code];\n        }\n        Tree[v].flag = true;\n    }\n\n    // la palabra existe si el camino existe y termina marcada\n    bool search(const string &word) {\n        int v = 0;\n        for (char ch : word) {\n            int code = ch - 'a';\n            if (Tree[v].children[code] == -1) return false;\n            v = Tree[v].children[code];\n        }\n        return Tree[v].flag;\n    }\n\n    // basta con que exista el camino del prefijo\n    bool startsWith(const string &prefix) {\n        int v = 0;\n        for (char ch : prefix) {\n            int code = ch - 'a';\n            if (Tree[v].children[code] == -1) return false;\n            v = Tree[v].children[code];\n        }\n        return true;\n    }\n};\n\nint main() {\n    fastio;\n    string s;\n    int k;\n    cin >> s >> k;\n    Trie PrefixTrie;\n    for (int i = 0; i < k; i++) {\n        string w;\n        cin >> w;\n        PrefixTrie.insert(w);\n    }\n\n    // dp[i] = formas de construir el sufijo s[i..]\n    int n = s.size();\n    // dp[i] = formas de construir el sufijo s[i..]\n    vector<ll> dp(n + 1, 0);\n    dp[n] = 1;\n    // desde cada posición se baja por el trie y cada palabra completa suma dp[j + 1]\n    for (int i = n - 1; i >= 0; i--) {\n        int v = 0;\n        for (int j = i; j < n; j++) {\n            int code = s[j] - 'a';\n            if (PrefixTrie.Tree[v].children[code] == -1) break;\n            v = PrefixTrie.Tree[v].children[code];\n            if (PrefixTrie.Tree[v].flag) dp[i] = (dp[i] + dp[j + 1]) % MODW;\n        }\n    }\n    cout << dp[0] << \"\\n\";\n    return 0;\n}\n"}, {"id": "Strings-Algorithms-RabinKarp", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/RabinKarp.cpp", "nombre": "RabinKarp", "algoritmo": "Rabin-Karp con doble hash polinomial", "problema": "CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)", "cses": "https://cses.fi/problemset/task/1753", "entrada": "texto s y luego patrón t (letras minúsculas)", "salida": "cantidad de apariciones de t en s", "complejidad": "tiempo O(|s| + |t|) esperado, memoria O(|s|)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Rabin-Karp con doble hash polinomial\n * Problema  : CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)\n * Entrada   : texto s y luego patrón t (letras minúsculas)\n * Salida    : cantidad de apariciones de t en s\n * Complejidad: tiempo O(|s| + |t|) esperado, memoria O(|s|)\n */\n\n// dos módulos y una base para reducir colisiones\nll P1 = 1000000007;\nll P2 = 998244353;\nll base = 60;\n\n// Pot[i] = base^i mod P\nvector<ll> Pot1(1000003, 1);\nvector<ll> Pot2(1000003, 1);\n\nll code(char a) {\n    return (ll)a - (ll)'a' + 1;\n}\n\nll mod(ll x, ll n) {\n    return (x % n + n) % n;\n}\n\n// hash polinomial de una cadena junto con su tamaño\nstruct Hash {\n    ll hash_1, hash_2, size;\n\n    Hash() { hash_1 = 0, hash_2 = 0, size = 0; }\n    Hash(ll h1, ll h2, ll s) { hash_1 = h1; hash_2 = h2; size = s; }\n    Hash(char s) { hash_1 = code(s), hash_2 = code(s), size = 1; }\n\n    // concatenación de dos hashes\n    Hash operator+(const Hash &other) const {\n        return Hash(mod(hash_1 * Pot1[other.size] + other.hash_1, P1),\n                    mod(hash_2 * Pot2[other.size] + other.hash_2, P2),\n                    size + other.size);\n    }\n\n    // quita un prefijo (hash del sufijo)\n    Hash operator-(const Hash &other) const {\n        return Hash(mod(hash_1 - other.hash_1 * Pot1[size - other.size], P1),\n                    mod(hash_2 - other.hash_2 * Pot2[size - other.size], P2),\n                    size - other.size);\n    }\n\n    bool operator==(const Hash &other) const {\n        return hash_1 == other.hash_1 && hash_2 == other.hash_2;\n    }\n};\n\nint main() {\n    fastio;\n    // potencias precalculadas\n    for (int i = 1; i < (int)Pot1.size(); i++) {\n        Pot1[i] = (base * Pot1[i - 1]) % P1;\n        Pot2[i] = (base * Pot2[i - 1]) % P2;\n    }\n\n    string s1, s2;\n    cin >> s1 >> s2;\n    if (s2.size() > s1.size()) {\n        cout << 0 << \"\\n\";\n        return 0;\n    }\n\n    // text[i] = hash del prefijo s1[0..i]\n    // text[i] = hash del prefijo s1[0..i]\n    vector<Hash> text;\n    text.push_back(Hash(s1.front()));\n    for (int i = 1; i < (int)s1.size(); i++)\n        text.push_back(text.back() + Hash(s1[i]));\n\n    Hash pattern;\n    for (auto c : s2) pattern = pattern + Hash(c);\n\n    int count = 0;\n    // se compara el hash de cada ventana con el del patrón\n    for (int i = 0; i + s2.size() <= s1.size(); i++) {\n        Hash search;\n        if (i == 0) search = text[s2.size() - 1];\n        else search = text[i + s2.size() - 1] - text[i - 1];\n        if (search == pattern) count++;\n    }\n    cout << count << \"\\n\";\n    return 0;\n}\n"}, {"id": "Strings-Algorithms-SuffixArray", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/SuffixArray.cpp", "nombre": "SuffixArray", "algoritmo": "Suffix Array (duplicación de prefijos) + LCP de Kasai", "problema": "CSES 2105 - Distinct Substrings (https://cses.fi/problemset/task/2105)", "cses": "https://cses.fi/problemset/task/2105", "entrada": "una cadena s", "salida": "cantidad de subcadenas distintas de s", "complejidad": "tiempo O(n log^2 n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Suffix Array (duplicación de prefijos) + LCP de Kasai\n * Problema  : CSES 2105 - Distinct Substrings (https://cses.fi/problemset/task/2105)\n * Entrada   : una cadena s\n * Salida    : cantidad de subcadenas distintas de s\n * Complejidad: tiempo O(n log^2 n), memoria O(n)\n */\n\n// sa = sufijos ordenados; rnk[i] = posición del sufijo i en ese orden\nvector<int> suffixArray(const string &s) {\n    int n = s.size();\n    vector<int> sa(n), rnk(n), tmp(n);\n    iota(all(sa), 0);\n    for (int i = 0; i < n; i++) rnk[i] = s[i];\n    // duplicación de prefijos: se ordena por los primeros k y luego 2k caracteres\n    for (int k = 1;; k <<= 1) {\n        auto cmp = [&](int a, int b) {\n            if (rnk[a] != rnk[b]) return rnk[a] < rnk[b];\n            int ra = a + k < n ? rnk[a + k] : -1;\n            int rb = b + k < n ? rnk[b + k] : -1;\n            return ra < rb;\n        };\n        sort(all(sa), cmp);\n        tmp[sa[0]] = 0;\n        for (int i = 1; i < n; i++) tmp[sa[i]] = tmp[sa[i - 1]] + cmp(sa[i - 1], sa[i]);\n        rnk = tmp;\n        if (rnk[sa[n - 1]] == n - 1) break;\n    }\n    return sa;\n}\n\n// lcp[i] = prefijo común entre sa[i] y sa[i + 1]\n// lcp[i] = prefijo común entre sa[i] y sa[i + 1] (Kasai)\nvector<int> kasai(const string &s, const vector<int> &sa) {\n    int n = s.size();\n    vector<int> rnk(n), lcp(max(0, n - 1));\n    for (int i = 0; i < n; i++) rnk[sa[i]] = i;\n    for (int i = 0, h = 0; i < n; i++) {\n        if (rnk[i] + 1 < n) {\n            int j = sa[rnk[i] + 1];\n            while (i + h < n && j + h < n && s[i + h] == s[j + h]) h++;\n            lcp[rnk[i]] = h;\n            if (h > 0) h--;\n        }\n        else h = 0;\n    }\n    return lcp;\n}\n\nint main() {\n    fastio;\n    string s;\n    cin >> s;\n    ll n = s.size();\n    auto sa = suffixArray(s);\n    auto lcp = kasai(s, sa);\n\n    // subcadenas distintas = todas las subcadenas - prefijos repetidos\n    // cada sufijo aporta (largo) subcadenas; se restan las que ya aparecieron (lcp)\n    ll total = n * (n + 1) / 2;\n    for (int x : lcp) total -= x;\n    cout << total << \"\\n\";\n    return 0;\n}\n"}, {"id": "Strings-Algorithms-ZFunction", "carpeta": "Strings", "area": "Cadenas", "sub": "Algorithms", "archivo": "Strings/Algorithms/ZFunction.cpp", "nombre": "ZFunction", "algoritmo": "Z-function", "problema": "CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)", "cses": "https://cses.fi/problemset/task/1753", "entrada": "dos líneas: el texto s y el patrón t", "salida": "número de apariciones de t en s", "complejidad": "tiempo O(|s| + |t|), memoria O(|s| + |t|)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Z-function\n * Problema  : CSES 1753 - String Matching (https://cses.fi/problemset/task/1753)\n * Entrada   : dos líneas: el texto s y el patrón t\n * Salida    : número de apariciones de t en s\n * Complejidad: tiempo O(|s| + |t|), memoria O(|s| + |t|)\n */\n\n// z[i] = longitud del prefijo comun mas largo entre s y s[i..]\nvector<int> z_function(const string &s) {\n    int n = s.size();\n    vector<int> z(n, 0);\n    for (int i = 1, l = 0, r = 0; i < n; i++) {\n        // dentro del intervalo [l, r) ya hay información reutilizable\n        if (i < r) z[i] = min(r - i, z[i - l]);\n        // se extiende comparando caracter a caracter\n        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;\n        // se actualiza el intervalo más a la derecha\n        if (i + z[i] > r) l = i, r = i + z[i];\n    }\n    return z;\n}\n\nint main() {\n    fastio;\n    string s, t;\n    cin >> s >> t;\n\n    // ocurrencias de t en s: z sobre t + '#' + s\n    string combined = t + '#' + s;\n    vector<int> z = z_function(combined);\n\n    ll count = 0;\n    for (int i = t.size() + 1; i < (int)combined.size(); i++)\n        // coincidencia completa del patrón en esa posición\n        if (z[i] == (int)t.size()) count++;\n\n    cout << count << \"\\n\";\n    return 0;\n}\n"}, {"id": "Geometry-ClosestPair", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/ClosestPair.cpp", "nombre": "ClosestPair", "algoritmo": "Par de puntos más cercano (sweep line con set)", "problema": "CSES 2194 - Minimum Euclidean Distance (https://cses.fi/problemset/task/2194)", "cses": "https://cses.fi/problemset/task/2194", "entrada": "n, luego n puntos enteros \"x y\"", "salida": "el cuadrado de la mínima distancia euclidiana entre dos puntos", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Par de puntos más cercano (sweep line con set)\n * Problema  : CSES 2194 - Minimum Euclidean Distance (https://cses.fi/problemset/task/2194)\n * Entrada   : n, luego n puntos enteros \"x y\"\n * Salida    : el cuadrado de la mínima distancia euclidiana entre dos puntos\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<pair<ll, ll>> p(n);\n    for (auto &q : p) cin >> q.first >> q.second;\n    // se ordenan los puntos por x\n    sort(all(p));  // ordenados por x\n\n    auto dist2 = [](pair<ll, ll> a, pair<ll, ll> b) {\n        return (a.first - b.first) * (a.first - b.first) + (a.second - b.second) * (a.second - b.second);\n    };\n\n    // set ordenado por y con los puntos dentro de la franja de ancho sqrt(best)\n    // puntos cercanos en x, ordenados por y\n    set<pair<ll, ll>> active;  // {y, x}\n    ll best = INF;\n    int left = 0;\n    for (int i = 0; i < n; i++) {\n        ll d = (ll)ceil(sqrt((ld)best));\n        if (best == INF) d = 4e9;\n        // se sacan los puntos demasiado lejos en x\n        while (left < i && p[i].first - p[left].first >= d) {\n            active.erase({p[left].second, p[left].first});\n            left++;\n        }\n        // solo se revisan los puntos con y dentro de ±d (pocos por la franja)\n        auto lo = active.lower_bound({p[i].second - d, -INF});\n        for (auto it = lo; it != active.end() && it->first <= p[i].second + d; ++it)\n            best = min(best, dist2(p[i], {it->second, it->first}));\n        active.insert({p[i].second, p[i].first});\n    }\n    cout << best << \"\\n\";\n    return 0;\n}\n"}, {"id": "Geometry-ConvexHull", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/ConvexHull.cpp", "nombre": "ConvexHull", "algoritmo": "Envolvente convexa (Graham scan, incluye puntos colineales del borde)", "problema": "CSES 2195 - Convex Hull (https://cses.fi/problemset/task/2195)", "cses": "https://cses.fi/problemset/task/2195", "entrada": "n, luego n puntos enteros \"x y\"", "salida": "cantidad de puntos de la envolvente (incluye los del borde) y sus coordenadas", "complejidad": "tiempo O(n log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Envolvente convexa (Graham scan, incluye puntos colineales del borde)\n * Problema  : CSES 2195 - Convex Hull (https://cses.fi/problemset/task/2195)\n * Entrada   : n, luego n puntos enteros \"x y\"\n * Salida    : cantidad de puntos de la envolvente (incluye los del borde) y sus coordenadas\n * Complejidad: tiempo O(n log n), memoria O(n)\n */\n\n// punto del plano con coordenadas enteras\nstruct pt {\n    ll x, y;  // Funcionan como parejas\n    bool operator==(pt const &t) const {\n        return x == t.x && y == t.y;\n    }\n};\n\n// signo del producto cruz (b - a) x (c - a)\nint orientation(pt a, pt b, pt c) {\n    ll v = a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y);  // Producto cruz\n    if (v < 0) return -1;  // a-b-c Horario\n    if (v > 0) return +1;  // a-b-c Antihorario\n    return 0;\n}\n\n// cw verifica si a-b-c va en sentido horario\nbool cw(pt a, pt b, pt c, bool include_collinear) {\n    int o = orientation(a, b, c);\n    return o < 0 || (include_collinear && o == 0);\n}\n\nbool collinear(pt a, pt b, pt c) { return orientation(a, b, c) == 0; }\n\n// Graham scan: se ordena por ángulo alrededor del punto más bajo\nvoid convex_hull(vector<pt> &a, bool include_collinear = false) {\n    pt p0 = *min_element(all(a), [](pt a, pt b) {\n        return make_pair(a.y, a.x) < make_pair(b.y, b.x);\n    });  // encuentra el punto más abajo a la izquierda\n    sort(all(a), [&p0](const pt &a, const pt &b) {\n        int o = orientation(p0, a, b);\n        if (o == 0)\n            return (p0.x - a.x) * (p0.x - a.x) + (p0.y - a.y) * (p0.y - a.y)\n                 < (p0.x - b.x) * (p0.x - b.x) + (p0.y - b.y) * (p0.y - b.y);\n        return o < 0;  // Criterio de comparacion para ordenar\n    });\n    // con puntos colineales en el borde final, se invierte esa última parte\n    if (include_collinear) {\n        int i = (int)a.size() - 1;\n        while (i >= 0 && collinear(p0, a[i], a.back())) i--;\n        reverse(a.begin() + i + 1, a.end());\n    }\n\n    // pila de la envolvente\n    vector<pt> st;\n    for (int i = 0; i < (int)a.size(); i++) {\n        // Verifica si los dos anteriores con el actual van en sentido horario\n        while (st.size() > 1 && !cw(st[st.size() - 2], st.back(), a[i], include_collinear))\n            st.pop_back();\n        st.push_back(a[i]);\n    }\n\n    // caso degenerado de puntos repetidos\n    if (include_collinear == false && st.size() == 2 && st[0] == st[1])\n        st.pop_back();\n\n    a = st;\n}\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<pt> points(n);\n    for (auto &p : points) cin >> p.x >> p.y;\n\n    convex_hull(points, true);\n    cout << points.size() << \"\\n\";\n    for (auto &p : points) cout << p.x << ' ' << p.y << \"\\n\";\n    return 0;\n}\n"}, {"id": "Geometry-Point", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/Point.cpp", "nombre": "Point", "algoritmo": "Vectores 3D (suma, producto punto y cruz, norma, proyección, ángulo)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "entrada": "seis reales: ax ay az bx by bz (para vectores en el plano, z = 0)", "salida": "a+b, a-b, a×b, a·b, |b| y la proyección de a sobre b (10 decimales)", "complejidad": "tiempo O(1) por operación, memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Vectores 3D (suma, producto punto y cruz, norma, proyección, ángulo)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : seis reales: ax ay az bx by bz (para vectores en el plano, z = 0)\n * Salida    : a+b, a-b, a×b, a·b, |b| y la proyección de a sobre b (10 decimales)\n * Complejidad: tiempo O(1) por operación, memoria O(1)\n */\n\nstruct Point3d {\n\tld x, y, z; //Son vectores y si lo necesita en el plano, pues fije z=0\n\tPoint3d() {}\n\tPoint3d(ld x, ld y, ld z): x(x), y(y), z(z) {}\n\tPoint3d& operator+=(const Point3d &t) {\n\t\tx += t.x;\n\t\ty += t.y;\n\t\tz += t.z;\n\t\treturn *this;\n\t}\n\tPoint3d& operator-=(const Point3d &t) {\n\t\tx -= t.x;\n\t\ty -= t.y;\n\t\tz -= t.z;\n\t\treturn *this;\n\t}\n\tPoint3d& operator*=(ld t) { //Aqui se opera a derecha!!\n\t\tx *= t;\n\t\ty *= t;\n\t\tz *= t;\n\t\treturn *this;\n\t}\n\tPoint3d& operator/=(ld t) { //Aqui se opera a derecha!!\n\t\tx /= t;\n\t\ty /= t;\n\t\tz /= t;\n\treturn *this;\n\t}\n\tPoint3d operator+(const Point3d &t) const {\n\t\treturn Point3d(*this) += t;\n\t}\n\tPoint3d operator-(const Point3d &t) const {\n\t\treturn Point3d(*this) -= t;\n\t}\n\tPoint3d operator*(ld t) const {\n\t\treturn Point3d(*this) *= t;\n\t}\n\tPoint3d operator/(ld t) const {\n\t\treturn Point3d(*this) /= t;\n\t}\n\t// producto punto\n\tstatic ld dot(Point3d a,Point3d b) {\n\t\treturn a.x * b.x + a.y * b.y + a.z * b.z;\n\t}\n\t// producto cruz\n\tstatic Point3d cross(Point3d a, Point3d b) {\n\t\treturn Point3d(a.y * b.z - a.z * b.y,\n\t\t\ta.z * b.x - a.x * b.z,\n\t\t\ta.x * b.y - a.y * b.x);\n\t}\n\tstatic ld norm(Point3d a) {//norma al cuadrado\n\t\treturn dot(a,a);\n\t}\n\tstatic ld abs(Point3d a) {//norma normal xd\n\t\treturn sqrt(norm(a));\n\t}\n\t// proyección de a sobre b: b * (a·b / |b|²)\n\tstatic Point3d proj(Point3d a, Point3d b) {// proyeccion de a en b\n\t\treturn b*(dot(a, b) / norm(b));\n\t}\n\t// ángulo entre dos vectores\n\tstatic ld angle(Point3d a, Point3d b) {\n\t\treturn acos(dot(a, b) / abs(a) / abs(b));\n\t}\n\t// igualdad con tolerancia EPS por ser reales\n\tbool operator==(const Point3d &other) const {\n    \t\tconst double EPS = 1e-6;\n\t\treturn fabs(x - other.x) < EPS && fabs(y - other.y) < EPS && fabs(z - other.z) < EPS;\n\t}\n};\nPoint3d operator*(ld a, Point3d b) {\n\treturn b * a;\n}\n\nint main() {\n    fastio;\n    precision(10);\n    ld ax, ay, az, bx, by, bz;\n    cin >> ax >> ay >> az >> bx >> by >> bz;\n    Point3d A(ax, ay, az), B(bx, by, bz);\n\n    Point3d sum = A + B, diff = A - B, cr = Point3d::cross(A, B), pr = Point3d::proj(A, B);\n    cout << \"A+B = \" << sum.x << ' ' << sum.y << ' ' << sum.z << \"\\n\";\n    cout << \"A-B = \" << diff.x << ' ' << diff.y << ' ' << diff.z << \"\\n\";\n    cout << \"AxB = \" << cr.x << ' ' << cr.y << ' ' << cr.z << \"\\n\";\n    cout << \"A.B = \" << Point3d::dot(A, B) << \"\\n\";\n    cout << \"|B| = \" << Point3d::abs(B) << \"\\n\";\n    cout << \"proj_B(A) = \" << pr.x << ' ' << pr.y << ' ' << pr.z << \"\\n\";\n    return 0;\n}\n"}, {"id": "Geometry-PointInPolygon", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/PointInPolygon.cpp", "nombre": "PointInPolygon", "algoritmo": "Punto en polígono (ray casting con producto cruz)", "problema": "CSES 2192 - Point in Polygon (https://cses.fi/problemset/task/2192)", "cses": "https://cses.fi/problemset/task/2192", "entrada": "n m, luego n vértices del polígono y m puntos \"x y\"", "salida": "INSIDE, OUTSIDE o BOUNDARY para cada punto", "complejidad": "tiempo O(n · m), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Punto en polígono (ray casting con producto cruz)\n * Problema  : CSES 2192 - Point in Polygon (https://cses.fi/problemset/task/2192)\n * Entrada   : n m, luego n vértices del polígono y m puntos \"x y\"\n * Salida    : INSIDE, OUTSIDE o BOUNDARY para cada punto\n * Complejidad: tiempo O(n · m), memoria O(n)\n */\n\ntypedef pair<ll, ll> pt;\n\n// producto cruz (b - a) x (c - a)\nll cross(pt a, pt b, pt c) {  // (b - a) x (c - a)\n    return (b.first - a.first) * (c.second - a.second) - (b.second - a.second) * (c.first - a.first);\n}\n\n// p está en el segmento ab: colineal y dentro de su caja\nbool onSegment(pt a, pt b, pt p) {\n    return cross(a, b, p) == 0 &&\n           min(a.first, b.first) <= p.first && p.first <= max(a.first, b.first) &&\n           min(a.second, b.second) <= p.second && p.second <= max(a.second, b.second);\n}\n\nint main() {\n    fastio;\n    int n, m;\n    cin >> n >> m;\n    vector<pt> poly(n);\n    for (auto &p : poly) cin >> p.first >> p.second;\n\n    while (m--) {\n        pt p;\n        cin >> p.first >> p.second;\n        bool boundary = false;\n        int crossings = 0;\n        for (int i = 0; i < n; i++) {\n            pt a = poly[i], b = poly[(i + 1) % n];\n            // si está sobre una arista, es borde\n            if (onSegment(a, b, p)) { boundary = true; break; }\n            // rayo hacia la derecha: cuenta aristas que cruzan la altura de p\n            // rayo horizontal: se cuentan aristas que cruzan la altura de p a su derecha\n            if ((a.second > p.second) != (b.second > p.second)) {\n                ll c = cross(a, b, p);\n                if ((c > 0) == (b.second > a.second)) crossings++;\n            }\n        }\n        if (boundary) cout << \"BOUNDARY\\n\";\n        // cantidad impar de cruces = adentro\n        else cout << (crossings % 2 ? \"INSIDE\" : \"OUTSIDE\") << \"\\n\";\n    }\n    return 0;\n}\n"}, {"id": "Geometry-PolygonLatticePoints", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/PolygonLatticePoints.cpp", "nombre": "PolygonLatticePoints", "algoritmo": "Teorema de Pick (puntos enteros de un polígono)", "problema": "CSES 2193 - Polygon Lattice Points (https://cses.fi/problemset/task/2193)", "cses": "https://cses.fi/problemset/task/2193", "entrada": "n, luego n vértices enteros en orden", "salida": "puntos enteros interiores y puntos enteros en el borde", "complejidad": "tiempo O(n log C), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Teorema de Pick (puntos enteros de un polígono)\n * Problema  : CSES 2193 - Polygon Lattice Points (https://cses.fi/problemset/task/2193)\n * Entrada   : n, luego n vértices enteros en orden\n * Salida    : puntos enteros interiores y puntos enteros en el borde\n * Complejidad: tiempo O(n log C), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    cin >> n;\n    vector<pair<ll, ll>> p(n);\n    for (auto &q : p) cin >> q.first >> q.second;\n\n    ll area2 = 0, boundary = 0;  // area2 = 2 * área\n    for (int i = 0; i < n; i++) {\n        auto [x1, y1] = p[i];\n        auto [x2, y2] = p[(i + 1) % n];\n        // Shoelace: suma de x1*y2 - x2*y1\n        area2 += x1 * y2 - x2 * y1;\n        // puntos enteros en cada arista = gcd(|dx|, |dy|)\n        boundary += gcd(abs(x2 - x1), abs(y2 - y1));\n    }\n    area2 = abs(area2);\n\n    // Pick: A = I + B/2 - 1  =>  I = (2A - B + 2) / 2\n    // de Pick: A = I + B/2 - 1\n    ll inside = (area2 - boundary + 2) / 2;\n    cout << inside << ' ' << boundary << \"\\n\";\n    return 0;\n}\n"}, {"id": "Geometry-SegmentIntersection", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/SegmentIntersection.cpp", "nombre": "SegmentIntersection", "algoritmo": "Intersección de segmentos (orientaciones y cajas envolventes)", "problema": "CSES 2190 - Line Segment Intersection (https://cses.fi/problemset/task/2190)", "cses": "https://cses.fi/problemset/task/2190", "entrada": "t casos con \"x1 y1 x2 y2 x3 y3 x4 y4\"", "salida": "YES si los segmentos se intersectan (incluye tocarse), NO si no", "complejidad": "tiempo O(1) por caso, memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Intersección de segmentos (orientaciones y cajas envolventes)\n * Problema  : CSES 2190 - Line Segment Intersection (https://cses.fi/problemset/task/2190)\n * Entrada   : t casos con \"x1 y1 x2 y2 x3 y3 x4 y4\"\n * Salida    : YES si los segmentos se intersectan (incluye tocarse), NO si no\n * Complejidad: tiempo O(1) por caso, memoria O(1)\n */\n\ntypedef pair<ll, ll> pt;\n\nint sgn(ll v) { return (v > 0) - (v < 0); }\n\n// signo del producto cruz: 1 antihorario, -1 horario, 0 colineal\nint orient(pt a, pt b, pt c) {\n    return sgn((b.first - a.first) * (c.second - a.second) - (b.second - a.second) * (c.first - a.first));\n}\n\n// los rectángulos de los segmentos deben solaparse (caso colineal)\nbool inBox(pt a, pt b, pt c, pt d) {  // las cajas de ab y cd se solapan\n    return max(min(a.first, b.first), min(c.first, d.first)) <= min(max(a.first, b.first), max(c.first, d.first)) &&\n           max(min(a.second, b.second), min(c.second, d.second)) <= min(max(a.second, b.second), max(c.second, d.second));\n}\n\n// los extremos de cada segmento quedan a lados opuestos del otro (o tocan)\nbool intersect(pt a, pt b, pt c, pt d) {\n    return inBox(a, b, c, d) &&\n           orient(a, b, c) * orient(a, b, d) <= 0 &&\n           orient(c, d, a) * orient(c, d, b) <= 0;\n}\n\nint main() {\n    fastio;\n    int t;\n    cin >> t;\n    while (t--) {\n        pt a, b, c, d;\n        cin >> a.first >> a.second >> b.first >> b.second >> c.first >> c.second >> d.first >> d.second;\n        cout << (intersect(a, b, c, d) ? \"YES\" : \"NO\") << \"\\n\";\n    }\n    return 0;\n}\n"}, {"id": "Geometry-Shoelace", "carpeta": "Geometry", "area": "Geometría", "sub": "-", "archivo": "Geometry/Shoelace.cpp", "nombre": "Shoelace", "algoritmo": "Fórmula del Shoelace (área de un polígono)", "problema": "CSES 2191 - Polygon Area (https://cses.fi/problemset/task/2191)", "cses": "https://cses.fi/problemset/task/2191", "entrada": "n, luego n vértices \"x y\" en orden", "salida": "el doble del área del polígono (entero)", "complejidad": "tiempo O(n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Fórmula del Shoelace (área de un polígono)\n * Problema  : CSES 2191 - Polygon Area (https://cses.fi/problemset/task/2191)\n * Entrada   : n, luego n vértices \"x y\" en orden\n * Salida    : el doble del área del polígono (entero)\n * Complejidad: tiempo O(n), memoria O(n)\n */\n\n// módulo no negativo para índices circulares\nll mod(ll x, ll n) {\n    return (x % n + n) % n;\n}\n\nint main() {\n    fastio;\n    ll n;\n    cin >> n;\n    vector<pair<ll, ll>> points(n);\n    for (auto &p : points) cin >> p.first >> p.second;\n\n    ll res = 0;\n    for (int i = 0; i < n; i++) {\n        // término x_i * (y_{i+1} - y_{i-1}) de la fórmula del Shoelace\n        res += points[i].first * (points[mod(i + 1, n)].second - points[mod(i - 1, n)].second);\n    }\n\n    res = abs(res);  // Esto me da 2 veces el area!!\n    cout << res << \"\\n\";\n    return 0;\n}\n"}, {"id": "FunctionalTools-Codes-BS-library", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/BS(library).cpp", "nombre": "BS(library)", "algoritmo": "Búsqueda binaria con la librería (binary_search / lower_bound)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "entrada": "n target, luego n enteros ordenados", "salida": "FOUND y su índice, o NOT FOUND", "complejidad": "tiempo O(log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Búsqueda binaria con la librería (binary_search / lower_bound)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n target, luego n enteros ordenados\n * Salida    : FOUND y su índice, o NOT FOUND\n * Complejidad: tiempo O(log n), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n; ll target;\n    cin >> n >> target;\n    vector<ll> a(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    // asume a[] ordenado\n    // binary_search solo responde si existe\n    bool found = binary_search(all(a), target);\n    if (found) {\n        cout << \"FOUND\\n\";\n        // posición con lower_bound:\n        // lower_bound da la primera posición con valor >= target\n        int idx = int(lower_bound(all(a), target) - a.begin());\n        cout << \"at index \" << idx << \"\\n\";\n    } else {\n        cout << \"NOT FOUND\\n\";\n    }\n    return 0;\n}\n"}, {"id": "FunctionalTools-Codes-BS", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/BS.cpp", "nombre": "BS", "algoritmo": "Búsqueda binaria manual", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "entrada": "n target, luego n enteros ordenados", "salida": "FOUND at index i, o NOT FOUND", "complejidad": "tiempo O(log n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Búsqueda binaria manual\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : n target, luego n enteros ordenados\n * Salida    : FOUND at index i, o NOT FOUND\n * Complejidad: tiempo O(log n), memoria O(n)\n */\n\n// devuelve el índice de target en a[] o -1 si no existe\n// mitad del rango en cada paso: se descarta la mitad donde no puede estar\nint binary_search_manual(const vector<ll>& a, ll target) {\n    int lo = 0, hi = int(a.size()) - 1;\n    while (lo <= hi) {\n        // mid se calcula así para evitar overflow\n        int mid = lo + (hi - lo) / 2;\n        if (a[mid] == target) return mid;\n        if (a[mid] < target) lo = mid + 1;\n        else hi = mid - 1;\n    }\n    return -1;\n}\n\nint main() {\n    fastio;\n    int n; ll target;\n    cin >> n >> target;\n    vector<ll> a(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    // asume a[] ordenado\n    // la búsqueda exige el arreglo ordenado\n    int idx = binary_search_manual(a, target);\n    if (idx != -1) cout << \"FOUND at index \" << idx << \"\\n\";\n    else cout << \"NOT FOUND\\n\";\n    return 0;\n}\n"}, {"id": "FunctionalTools-Codes-BinarySearchAnswer", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/BinarySearchAnswer.cpp", "nombre": "BinarySearchAnswer", "algoritmo": "Búsqueda binaria sobre la respuesta", "problema": "CSES 1620 - Factory Machines (https://cses.fi/problemset/task/1620)", "cses": "https://cses.fi/problemset/task/1620", "entrada": "n t, luego n tiempos k_i (una máquina produce un producto cada k_i segundos)", "salida": "mínimo tiempo para producir t productos", "complejidad": "tiempo O(n log(t · k_min)), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Búsqueda binaria sobre la respuesta\n * Problema  : CSES 1620 - Factory Machines (https://cses.fi/problemset/task/1620)\n * Entrada   : n t, luego n tiempos k_i (una máquina produce un producto cada k_i segundos)\n * Salida    : mínimo tiempo para producir t productos\n * Complejidad: tiempo O(n log(t · k_min)), memoria O(n)\n */\n\nint main() {\n    fastio;\n    int n;\n    ll t;\n    cin >> n >> t;\n    vector<ll> k(n);\n    for (auto &x : k) cin >> x;\n\n    // la respuesta es monótona: si en \"time\" alcanza, en más tiempo también\n    // cota superior: la máquina más rápida sola produce t productos en k_min * t\n    ll lo = 1, hi = *min_element(all(k)) * t;\n    // se busca el menor tiempo que alcanza\n    while (lo < hi) {\n        ll mid = lo + (hi - lo) / 2;\n        ll made = 0;\n        for (ll x : k) {\n            // cada máquina produce mid / k_i productos\n            made += mid / x;\n            if (made >= t) break;\n        }\n        // alcanza: se prueba con menos tiempo; si no, con más\n        if (made >= t) hi = mid;\n        else lo = mid + 1;\n    }\n    cout << lo << \"\\n\";\n    return 0;\n}\n"}, {"id": "FunctionalTools-Codes-GrayCode", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/GrayCode.cpp", "nombre": "GrayCode", "algoritmo": "Código de Gray (i ^ (i >> 1))", "problema": "CSES 2205 - Gray Code (https://cses.fi/problemset/task/2205)", "cses": "https://cses.fi/problemset/task/2205", "entrada": "n", "salida": "los 2^n códigos de Gray de n bits, uno por línea", "complejidad": "tiempo O(2^n · n), memoria O(n)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Código de Gray (i ^ (i >> 1))\n * Problema  : CSES 2205 - Gray Code (https://cses.fi/problemset/task/2205)\n * Entrada   : n\n * Salida    : los 2^n códigos de Gray de n bits, uno por línea\n * Complejidad: tiempo O(2^n · n), memoria O(n)\n */\n\nint main(){\n    fastio;\n \n    ll n; cin >> n;\n    // hay 2^n códigos\n    for(int i = 0; i < (1<<n); ++i){\n        // código Gray del número i: i XOR (i >> 1)\n        ll gn = (i^(i >> 1));\n        // se escribe gn en binario con n bits\n        string res = \"\";\n        for(int i = 0; i < n; i++){\n            if(gn & (1 << i)) res += \"1\";\n            else res += \"0\";\n        }\n        // los bits se armaron del menos al más significativo, se invierten\n        reverse(all(res));\n        cout << res  << \"\\n\";\n    }\n}\n"}, {"id": "FunctionalTools-Codes-MatrixExponentiation", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/MatrixExponentiation.cpp", "nombre": "MatrixExponentiation", "algoritmo": "Exponenciación de matrices (Fibonacci en O(log n))", "problema": "CSES 1722 - Fibonacci Numbers (https://cses.fi/problemset/task/1722)", "cses": "https://cses.fi/problemset/task/1722", "entrada": "n", "salida": "F(n) módulo 10^9+7", "complejidad": "tiempo O(k^3 log n), k = 2, memoria O(k^2)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Exponenciación de matrices (Fibonacci en O(log n))\n * Problema  : CSES 1722 - Fibonacci Numbers (https://cses.fi/problemset/task/1722)\n * Entrada   : n\n * Salida    : F(n) módulo 10^9+7\n * Complejidad: tiempo O(k^3 log n), k = 2, memoria O(k^2)\n */\n\nconst ll MODM = 1000000007;  // este problema pide módulo 10^9+7\n\n// matriz cuadrada\ntypedef vector<vector<ll>> Matrix;\n\n// producto de matrices módulo MODM\nMatrix multiply(const Matrix &A, const Matrix &B) {\n    int k = A.size();\n    Matrix C(k, vector<ll>(k, 0));\n    for (int i = 0; i < k; i++)\n        for (int j = 0; j < k; j++)\n            for (int l = 0; l < k; l++)\n                C[i][j] = (C[i][j] + A[i][l] * B[l][j]) % MODM;\n    return C;\n}\n\n// exponenciación binaria: eleva la matriz en O(log e) multiplicaciones\nMatrix power(Matrix A, ll e) {\n    int k = A.size();\n    Matrix R(k, vector<ll>(k, 0));\n    for (int i = 0; i < k; i++) R[i][i] = 1;\n    while (e > 0) {\n        if (e & 1) R = multiply(R, A);\n        A = multiply(A, A);\n        e >>= 1;\n    }\n    return R;\n}\n\nint main() {\n    fastio;\n    ll n;\n    cin >> n;\n    // [F(n+1) F(n); F(n) F(n-1)] = [[1,1],[1,0]]^n\n    // matriz de Fibonacci\n    Matrix M = {{1, 1}, {1, 0}};\n    cout << power(M, n)[0][1] << \"\\n\";\n    return 0;\n}\n"}, {"id": "FunctionalTools-Codes-MeetInTheMiddle", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/MeetInTheMiddle.cpp", "nombre": "MeetInTheMiddle", "algoritmo": "Meet in the middle (subconjuntos con suma x)", "problema": "CSES 1628 - Meet in the Middle (https://cses.fi/problemset/task/1628)", "cses": "https://cses.fi/problemset/task/1628", "entrada": "n x, luego n enteros", "salida": "cantidad de subconjuntos cuya suma es x", "complejidad": "tiempo O(2^(n/2) · n), memoria O(2^(n/2))", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Meet in the middle (subconjuntos con suma x)\n * Problema  : CSES 1628 - Meet in the Middle (https://cses.fi/problemset/task/1628)\n * Entrada   : n x, luego n enteros\n * Salida    : cantidad de subconjuntos cuya suma es x\n * Complejidad: tiempo O(2^(n/2) · n), memoria O(2^(n/2))\n */\n\n// todas las sumas de subconjuntos de a[l..r)\n// genera 2^(r-l) sumas duplicando la lista con cada elemento\nvector<ll> subsetSums(const vector<ll> &a, int l, int r) {\n    vector<ll> sums = {0};\n    for (int i = l; i < r; i++) {\n        int sz = sums.size();\n        for (int j = 0; j < sz; j++) sums.push_back(sums[j] + a[i]);\n    }\n    return sums;\n}\n\nint main() {\n    fastio;\n    int n;\n    ll x;\n    cin >> n >> x;\n    vector<ll> a(n);\n    for (auto &v : a) cin >> v;\n\n    // se divide el arreglo en dos mitades\n    vector<ll> L = subsetSums(a, 0, n / 2), R = subsetSums(a, n / 2, n);\n    // R ordenado para buscar con búsqueda binaria\n    sort(all(R));\n    ll count = 0;\n    for (ll s : L)\n        // para cada suma de la mitad izquierda se cuentan las de la derecha que completan x\n        count += upper_bound(all(R), x - s) - lower_bound(all(R), x - s);\n    cout << count << \"\\n\";\n    return 0;\n}\n"}, {"id": "FunctionalTools-Codes-ModArithmetic", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/ModArithmetic.cpp", "nombre": "ModArithmetic", "algoritmo": "Exponenciación binaria, inverso modular y nCr", "problema": "CSES 1079 - Binomial Coefficients (https://cses.fi/problemset/task/1079)", "cses": "https://cses.fi/problemset/task/1079", "entrada": "t, luego t pares \"a b\"", "salida": "C(a, b) módulo 10^9 + 7", "complejidad": "tiempo O(10^6 + t), memoria O(10^6)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 1000000007\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Exponenciación binaria, inverso modular y nCr\n * Problema  : CSES 1079 - Binomial Coefficients (https://cses.fi/problemset/task/1079)\n * Entrada   : t, luego t pares \"a b\"\n * Salida    : C(a, b) módulo 10^9 + 7\n * Complejidad: tiempo O(10^6 + t), memoria O(10^6)\n */\n\n// fact[i] = i! y inv_fact[i] = inverso de i!, ambos módulo MOD\nconst int MAXN = 1000001;\nvector<ll> fact(MAXN), inv_fact(MAXN);\n\n// a^b mod MOD en O(log b)\nll binpow(ll a, ll b) {\n    ll res = 1;\n    a %= MOD;\n    while (b > 0) {\n        if (b & 1) res = res * a % MOD;\n        a = a * a % MOD;\n        b >>= 1;\n    }\n    return res;\n}\n\n// inverso modular (MOD debe ser primo): a^(MOD-2)\nll mod_inv(ll a) {\n    return binpow(a, MOD - 2);\n}\n\n// se precalculan factoriales e inversos en O(MAXN)\nvoid precompute() {\n    fact[0] = 1;\n    for (int i = 1; i < MAXN; i++) fact[i] = fact[i - 1] * i % MOD;\n    // inverso del último factorial con Fermat\n    inv_fact[MAXN - 1] = mod_inv(fact[MAXN - 1]);\n    // los demás inversos salen de inv_fact[i-1] = inv_fact[i] * i\n    for (int i = MAXN - 1; i > 0; i--) inv_fact[i - 1] = inv_fact[i] * i % MOD;\n}\n\n// C(n, k) mod MOD\nll nCr(int n, int k) {\n    if (k < 0 || k > n) return 0;\n    return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD;\n}\n\nint main() {\n    fastio;\n    precompute();\n    int t; cin >> t;\n    while (t--) {\n        int a, b; cin >> a >> b;\n        cout << nCr(a, b) << \"\\n\";\n    }\n    return 0;\n}\n"}, {"id": "FunctionalTools-Codes-Sieve", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/Sieve.cpp", "nombre": "Sieve", "algoritmo": "Criba de Eratóstenes y criba segmentada", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "entrada": "N, luego L R", "salida": "primos ≤ N y luego los primos en [L, R]", "complejidad": "tiempo O(N log log N) y O((R-L) log log R), memoria O(N + R - L)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Criba de Eratóstenes y criba segmentada\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : N, luego L R\n * Salida    : primos ≤ N y luego los primos en [L, R]\n * Complejidad: tiempo O(N log log N) y O((R-L) log log R), memoria O(N + R - L)\n */\n\n// Criba de Eratóstenes: marca en `is_prime` los primos ≤ N.\n// is_prime[x] queda en true si x es primo\nvector<bool> sieve(int N) {\n    vector<bool> is_prime(N+1, true);\n    is_prime[0] = is_prime[1] = false;\n    // solo hace falta tachar múltiplos de primos hasta sqrt(N)\n    for (int p = 2; p*p <= N; ++p) {\n        if (is_prime[p]) {\n            for (int x = p*p; x <= N; x += p)\n                is_prime[x] = false;\n        }\n    }\n    return is_prime;\n}\n\n// Criba segmentada: devuelve todos los primos en [L..R], dados los primos ≤ sqrt(R).\n// criba por segmentos: se tachan los múltiplos de los primos pequeños dentro de [L, R]\nvector<ll> segmented_sieve(ll L, ll R) {\n    ll lim = floor(sqrt(R));\n    auto base = sieve(lim);\n    vector<ll> primes;\n    for (int i = 2; i <= lim; ++i)\n        if (base[i]) primes.push_back(i);\n\n    ll sz = R - L + 1;\n    vector<bool> is_prime(sz, true);\n    if (L <= 1) {\n        for (ll x = L; x <= min(R, 1LL); ++x) is_prime[x - L] = false;\n    }\n    for (ll p : primes) {\n        // primer múltiplo de p dentro del rango (sin tachar a p mismo)\n        ll start = max(p*p, ((L + p - 1)/p)*p);\n        for (ll x = start; x <= R; x += p)\n            is_prime[x - L] = false;\n    }\n\n    vector<ll> segment;\n    for (ll i = 0; i < sz; ++i) {\n        if (is_prime[i]) segment.push_back(L + i);\n    }\n    return segment;\n}\n\nint main() {\n    fastio;\n    // Ejemplo de uso:\n    int N; \n    cin >> N;\n    auto small = sieve(N);\n    // imprime primos ≤ N\n    for (int i = 2; i <= N; ++i)\n        if (small[i]) cout << i << ' ';\n    cout << '\\n';\n\n    ll L, R;\n    cin >> L >> R;\n    auto seg = segmented_sieve(L, R);\n    // imprime primos en [L..R]\n    for (ll p : seg) cout << p << ' ';\n    cout << '\\n';\n\n    return 0;\n}\n"}, {"id": "FunctionalTools-Codes-TS", "carpeta": "FunctionalTools", "area": "Herramientas", "sub": "Codes", "archivo": "FunctionalTools/Codes/TS.cpp", "nombre": "TS", "algoritmo": "Búsqueda ternaria (máximo de una función unimodal)", "problema": "Sin problema equivalente en CSES; formato propio", "cses": "", "entrada": "L R", "salida": "el máximo de f(x) = -(x-3)^2 + 10 en [L, R]", "complejidad": "tiempo O(log(R-L)), memoria O(1)", "codigo": "#include <bits/stdc++.h>\n\nusing namespace std;\ntypedef long long ll;\ntypedef long double ld;\nconst ll INF = numeric_limits<ll>::max();\n\n#define all(x) x.begin(), x.end()\n#define rall(x) x.rbegin(), x.rend()\n#define MOD 998244353\n#define pi acos(-1)\n#define gcd __gcd\n#define lcm(a, b) ((a) * (b) / gcd(a, b))\n#define precision(n) cout << fixed << setprecision(n)\n#define debug(arr) cerr << #arr << \" = \"; for (auto &x : arr) cerr << x << \" \"; cerr << endl;\n#define fastio ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);\n\n/*\n * Algoritmo : Búsqueda ternaria (máximo de una función unimodal)\n * Problema  : Sin problema equivalente en CSES; formato propio\n * Entrada   : L R\n * Salida    : el máximo de f(x) = -(x-3)^2 + 10 en [L, R]\n * Complejidad: tiempo O(log(R-L)), memoria O(1)\n */\n\n// asume f es unimodal (primero crece luego decrece) en [l..r]\n// se descarta un tercio del intervalo en cada paso\nll ternary_search(int l, int r, function<ll(int)> f) {\n    while (r - l > 3) {\n        int m1 = l + (r - l) / 3;\n        int m2 = r - (r - l) / 3;\n        if (f(m1) < f(m2))\n            l = m1;\n        else\n            r = m2;\n    }\n    // al quedar pocos valores se revisan uno por uno\n    ll best = f(l);\n    for (int i = l+1; i <= r; i++)\n        best = max(best, f(i));\n    return best;\n}\n\nint main() {\n    fastio;\n    int L, R;\n    cin >> L >> R;\n    // ejemplo: f(x) = -(x-3)^2 + 10  (unimodal)\n    auto f = [&](int x){ return -(ll)(x-3)*(x-3) + 10; };\n    ll ans = ternary_search(L, R, f);\n    cout << ans << \"\\n\";\n    return 0;\n}\n"}];
